### 1. Server Code (`server.js`)

This server handles connection management, room logic, message history, and broadcasting without any external web frameworks.

```javascript
const WebSocket = require('ws');
const http = require('http');
const fs = require('fs');
const path = require('path');

const PORT = 8080;
const MAX_HISTORY = 50;

// In-memory storage
const rooms = new Map(); // Map<roomName, Map<ws, nickname>>
const history = new Map(); // Map<roomName, Array<messageObject>>

// Helper to get or create room data
function getRoom(roomName) {
    if (!rooms.has(roomName)) {
        rooms.set(roomName, new Map());
        history.set(roomName, []);
    }
    return {
        users: rooms.get(roomName),
        messages: history.get(roomName)
    };
}

// Helper to broadcast to a specific room
function broadcastToRoom(roomName, message, excludeWs = null) {
    const roomData = getRoom(roomName);
    const payload = JSON.stringify(message);

    roomData.users.forEach((nickname, ws) => {
        if (ws !== excludeWs && ws.readyState === WebSocket.OPEN) {
            ws.send(payload);
        }
    });
}

// Helper to send system message
function sendSystemMessage(roomName, text) {
    broadcastToRoom(roomName, {
        type: 'system',
        room: roomName,
        content: text,
        timestamp: new Date().toISOString()
    });
}

const wss = new WebSocket.Server({ port: PORT });

// Serve the HTML client
const server = http.createServer((req, res) => {
    if (req.url === '/' || req.url === '/index.html') {
        fs.readFile(path.join(__dirname, 'index.html'), (err, data) => {
            if (err) {
                res.writeHead(500);
                res.end('Error loading index.html');
                return;
            }
            res.writeHead(200, { 'Content-Type': 'text/html' });
            res.end(data);
        });
    } else {
        res.writeHead(404);
        res.end('Not found');
    }
});

server.listen(PORT, () => {
    console.log(`Server running at http://localhost:${PORT}`);
});

wss.on('connection', (ws) => {
    let currentRoom = null;
    let nickname = null;

    ws.on('message', (data) => {
        let message;
        try {
            message = JSON.parse(data);
        } catch (e) {
            ws.send(JSON.stringify({ type: 'error', content: 'Invalid JSON' }));
            return;
        }

        switch (message.type) {
            case 'join':
                // Leave previous room if any
                if (currentRoom) {
                    const prevRoomData = getRoom(currentRoom);
                    prevRoomData.users.delete(ws);
                    sendSystemMessage(currentRoom, `${nickname} left the room.`);
                }

                currentRoom = message.room || 'general';
                nickname = message.nickname || `Guest_${Math.floor(Math.random() * 1000)}`;

                const roomData = getRoom(currentRoom);
                roomData.users.set(ws, nickname);

                // Send history to the new user
                ws.send(JSON.stringify({
                    type: 'history',
                    room: currentRoom,
                    messages: roomData.messages
                }));

                // Announce join
                sendSystemMessage(currentRoom, `${nickname} joined the room.`);
                break;

            case 'chat':
                if (!currentRoom || !nickname) return;

                const chatMsg = {
                    type: 'chat',
                    room: currentRoom,
                    user: nickname,
                    content: message.content,
                    timestamp: new Date().toISOString()
                };

                // Add to history
                const hist = getRoom(currentRoom).messages;
                hist.push(chatMsg);
                if (hist.length > MAX_HISTORY) hist.shift();

                // Broadcast
                broadcastToRoom(currentRoom, chatMsg);
                break;

            case 'typing':
                if (!currentRoom || !nickname) return;
                broadcastToRoom(currentRoom, {
                    type: 'typing',
                    room: currentRoom,
                    user: nickname,
                    timestamp: new Date().toISOString()
                }, ws); // Exclude sender
                break;

            case 'leave':
                if (currentRoom) {
                    const roomData = getRoom(currentRoom);
                    roomData.users.delete(ws);
                    sendSystemMessage(currentRoom, `${nickname} left the room.`);
                    currentRoom = null;
                }
                break;
        }
    });

    ws.on('close', () => {
        if (currentRoom) {
            const roomData = getRoom(currentRoom);
            roomData.users.delete(ws);
            sendSystemMessage(currentRoom, `${nickname} left the room.`);
        }
    });
});
```

