## Server Code (`server.js`)

```javascript
const WebSocket = require('ws');
const http = require('http');
const fs = require('fs');
const path = require('path');

const PORT = 3000;

// Create HTTP server to serve the client
const server = http.createServer((req, res) => {
  if (req.url === '/' || req.url === '/index.html') {
    fs.readFile(path.join(__dirname, 'client.html'), (err, data) => {
      if (err) {
        res.writeHead(500);
        res.end('Error loading client.html');
        return;
      }
      res.writeHead(200, { 'Content-Type': 'text/html' });
      res.end(data);
    });
  } else {
    res.writeHead(404);
    res.end('Not found');
  }
});

// Create WebSocket server
const wss = new WebSocket.Server({ server });

// Data structures
const rooms = new Map(); // roomName -> { messages: [], users: Set() }
const clients = new Map(); // ws -> { nickname: string, room: string, typingTimeout: timeout }

// Initialize default rooms
['general', 'random', 'tech'].forEach(roomName => {
  rooms.set(roomName, { messages: [], users: new Set() });
});

// Helper functions
function getRoom(roomName) {
  if (!rooms.has(roomName)) {
    rooms.set(roomName, { messages: [], users: new Set() });
  }
  return rooms.get(roomName);
}

function addMessage(roomName, message) {
  const room = getRoom(roomName);
  room.messages.push(message);

  // Keep only last 50 messages
  if (room.messages.length > 50) {
    room.messages.shift();
  }
}

function createMessage(type, room, user, content, data = {}) {
  return {
    type,
    room,
    user,
    content,
    timestamp: new Date().toISOString(),
    ...data
  };
}

function broadcastToRoom(roomName, message, excludeWs = null) {
  const messageStr = JSON.stringify(message);

  wss.clients.forEach(client => {
    if (client.readyState === WebSocket.OPEN && 
        clients.has(client) && 
        clients.get(client).room === roomName &&
        client !== excludeWs) {
      client.send(messageStr);
    }
  });
}

function sendToClient(ws, message) {
  if (ws.readyState === WebSocket.OPEN) {
    ws.send(JSON.stringify(message));
  }
}

function getUsersInRoom(roomName) {
  const users = [];
  clients.forEach((clientData, ws) => {
    if (clientData.room === roomName) {
      users.push(clientData.nickname);
    }
  });
  return users;
}

function removeUserFromRoom(ws) {
  const clientData = clients.get(ws);
  if (!clientData || !clientData.room) return;

  const room = getRoom(clientData.room);
  room.users.delete(clientData.nickname);

  // Clear typing timeout if exists
  if (clientData.typingTimeout) {
    clearTimeout(clientData.typingTimeout);
  }

  // Broadcast system message
  const systemMsg = createMessage(
    'system',
    clientData.room,
    'System',
    `${clientData.nickname} left the room`
  );
  addMessage(clientData.room, systemMsg);
  broadcastToRoom(clientData.room, systemMsg);

  // Send updated user list
  const userListMsg = createMessage(
    'userlist',
    clientData.room,
    'System',
    '',
    { users: getUsersInRoom(clientData.room) }
  );
  broadcastToRoom(clientData.room, userListMsg);
}

function addUserToRoom(ws, roomName) {
  const clientData = clients.get(ws);
  if (!clientData) return;

  clientData.room = roomName;
  const room = getRoom(roomName);
  room.users.add(clientData.nickname);

  // Send message history
  sendToClient(ws, createMessage(
    'history',
    roomName,
    'System',
    '',
    { messages: room.messages }
  ));

  // Send user list
  sendToClient(ws, createMessage(
    'userlist',
    roomName,
    'System',
    '',
    { users: getUsersInRoom(roomName) }
  ));

  // Broadcast system message
  const systemMsg = createMessage(
    'system',
    roomName,
    'System',
    `${clientData.nickname} joined the room`
  );
  addMessage(roomName, systemMsg);
  broadcastToRoom(roomName, systemMsg);

  // Broadcast updated user list
  const userListMsg = createMessage(
    'userlist',
    roomName,
    'System',
    '',
    { users: getUsersInRoom(roomName) }
  );
  broadcastToRoom(roomName, userListMsg);
}

// WebSocket connection handler
wss.on('connection', (ws) => {
  console.log('New client connected');

  ws.on('message', (data) => {
    try {
      const message = JSON.parse(data);
      const clientData = clients.get(ws);

      switch (message.type) {
        case 'setnick':
          // Set nickname on first connection
          if (!clientData) {
            const nickname = message.content.trim() || `User${Date.now()}`;
            clients.set(ws, { nickname, room: null, typingTimeout: null });

            sendToClient(ws, createMessage(
              'nickset',
              '',
              'System',
              `Nickname set to: ${nickname}`,
              { nickname }
            ));

            // Send available rooms
            sendToClient(ws, createMessage(
              'roomlist',
              '',
              'System',
              '',
              { rooms: Array.from(rooms.keys()) }
            ));
          }
          break;

        case 'join':
          if (!clientData) {
            sendToClient(ws, createMessage('error', '', 'System', 'Set nickname first'));
            return;
          }

          // Leave current room if in one
          if (clientData.room) {
            removeUserFromRoom(ws);
          }

          // Join new room
          const roomToJoin = message.room || 'general';
          addUserToRoom(ws, roomToJoin);
          break;

        case 'leave':
          if (clientData && clientData.room) {
            removeUserFromRoom(ws);
            clientData.room = null;
          }
          break;

        case 'message':
          if (!clientData || !clientData.room) {
            sendToClient(ws, createMessage('error', '', 'System', 'Join a room first'));
            return;
          }

          const chatMsg = createMessage(
            'message',
            clientData.room,
            clientData.nickname,
            message.content
          );

          addMessage(clientData.room, chatMsg);
          broadcastToRoom(clientData.room, chatMsg);
          sendToClient(ws, chatMsg); // Echo back to sender
          break;

        case 'typing':
          if (!clientData || !clientData.room) return;

          // Clear existing timeout
          if (clientData.typingTimeout) {
            clearTimeout(clientData.typingTimeout);
          }

          // Broadcast typing indicator
          const typingMsg = createMessage(
            'typing',
            clientData.room,
            clientData.nickname,
            '',
            { isTyping: message.isTyping }
          );
          broadcastToRoom(clientData.room, typingMsg, ws);

          // Auto-stop typing after 3 seconds
          if (message.isTyping) {
            clientData.typingTimeout = setTimeout(() => {
              const stopTypingMsg = createMessage(
                'typing',
                clientData.room,
                clientData.nickname,
                '',
                { isTyping: false }
              );
              broadcastToRoom(clientData.room, stopTypingMsg, ws);
            }, 3000);
          }
          break;

        default:
          sendToClient(ws, createMessage('error', '', 'System', 'Unknown message type'));
      }
    } catch (err) {
      console.error('Error processing message:', err);
      sendToClient(ws, createMessage('error', '', 'System', 'Invalid message format'));
    }
  });

  ws.on('close', () => {
    console.log('Client disconnected');
    removeUserFromRoom(ws);
    clients.delete(ws);
  });

  ws.on('error', (err) => {
    console.error('WebSocket error:', err);
  });

  // Send welcome message
  sendToClient(ws, createMessage(
    'welcome',
    '',
    'System',
    'Welcome to the chat server! Please set your nickname.'
  ));
});

server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
