Here is the complete, runnable Python CLI tool `fstats`. It uses only the standard library, implementing custom logic for table rendering, hashing, and optional ANSI color support without external dependencies.

### `fstats.py`

```python
#!/usr/bin/env python3
"""
fstats - A CLI tool for file statistics and directory comparison.
"""

import argparse
import os
import sys
import hashlib
import fnmatch
import time
import json
import csv
import io
from collections import defaultdict
from datetime import datetime
from pathlib import Path
from typing import Dict, List, Tuple, Any, Optional, Set

# --- Color Handling (No external deps) ---

class Colors:
    """ANSI Color codes with auto-detection."""
    DISABLED = False
    RESET = "\033[0m"
    RED = "\033[91m"
    GREEN = "\033[92m"
    YELLOW = "\033[93m"
    BLUE = "\033[94m"
    CYAN = "\033[96m"
    BOLD = "\033[1m"

    @classmethod
    def enable(cls):
        if sys.stdout.isatty():
            cls.DISABLED = False
        else:
            cls.DISABLED = True

    @classmethod
    def disable(cls):
        cls.DISABLED = True

    @classmethod
    def wrap(cls, color: str, text: str) -> str:
        if cls.DISABLED:
            return text
        return f"{color}{text}{cls.RESET}"

def c_red(t): return Colors.wrap(Colors.RED, t)
def c_green(t): return Colors.wrap(Colors.GREEN, t)
def c_yellow(t): return Colors.wrap(Colors.YELLOW, t)
def c_blue(t): return Colors.wrap(Colors.BLUE, t)
def c_cyan(t): return Colors.wrap(Colors.CYAN, t)
def c_bold(t): return Colors.wrap(Colors.BOLD, t)

# --- Helper Functions ---

def get_file_hash(filepath: str, chunk_size: 8192) -> str:
    """Calculate MD5 hash of a file."""
    hash_md5 = hashlib.md5()
    try:
        with open(filepath, "rb") as f:
            for chunk in iter(lambda: f.read(chunk_size), b""):
                hash_md5.update(chunk)
        return hash_md5.hexdigest()
    except (IOError, OSError):
        return ""

def format_size(size_bytes: int) -> str:
    """Convert bytes to human readable string."""
    if size_bytes == 0:
        return "0 B"
    units = ["B", "KB", "MB", "GB", "TB"]
    i = 0
    size = float(size_bytes)
    while size >= 1024 and i < len(units) - 1:
        size /= 1024
        i += 1
    return f"{size:.2f} {units[i]}"

def format_age(seconds: float) -> str:
    """Convert seconds to human readable age."""
    days = seconds / 86400
    if days < 1:
        return f"{days:.1f} days"
    elif days < 365:
        return f"{days/30:.1f} months"
    else:
        return f"{days/365:.1f} years"

def should_exclude(path: str, patterns: List[str]) -> bool:
    """Check if path matches any exclude glob pattern."""
    if not patterns:
        return False
    name = os.path.basename(path)
    for pattern in patterns:
        if fnmatch.fnmatch(name, pattern) or fnmatch.fnmatch(path, pattern):
            return True
    return False

def scan_directory(root_path: str, exclude_patterns: List[str], show_progress: bool = True):
    """
    Generator that yields file info. 
    Returns: (relative_path, absolute_path, size, mtime, extension)
    """
    root = Path(root_path).resolve()
    files = []

    # First pass to count for progress (optional, keeps memory low if we just estimate)
    # For true progress without loading all in memory, we'd need a two-pass or estimate.
    # Here we will do a simple yield with a counter.

    count = 0
    total_estimated = 0

    # Quick estimate for progress bar (counting entries)
    if show_progress:
        try:
            total_estimated = sum(1 for _ in os.scandir(root)) # Rough estimate for root only to avoid deep scan delay
            # Note: Accurate total requires full walk first. We'll use a dynamic spinner instead of % for deep trees
            # to avoid double-scanning performance hit.
        except PermissionError:
            pass

    if show_progress:
        print(c_cyan("Scanning directory..."), end='\r', file=sys.stderr)

    for dirpath, dirnames, filenames in os.walk(root):
        # Filter directories in-place to skip excluded folders
        dirnames[:] = [d for d in dirnames if not should_exclude(d, exclude_patterns)]

        for filename in filenames:
            if should_exclude(filename, exclude_patterns):
                continue

            abs_path = os.path.join(dirpath, filename)
            rel_path = os.path.relpath(abs_path, root)

            try:
                stat_info = os.stat(abs_path)
                size = stat_info.st_size
                mtime = stat_info.st_mtime
                _, ext = os.path.splitext(filename)
                ext = ext.lower() if ext else "(no ext)"

                count += 1
                if show_progress and count % 500 == 0:
                    print(c_cyan(f"Scanned {count} files..."), end='\r', file=sys.stderr)

                yield {
                    "rel_path": rel_path,
                    "abs_path": abs_path,
                    "size": size,
                    "mtime": mtime,
                    "ext": ext
                }
            except (PermissionError, FileNotFoundError):
                continue

    if show_progress:
        print(f"{' ' * 40}\r", end='', file=sys.stderr) # Clear line
        print(c_green(f"Scan complete: {count} files found."), file=sys.stderr)

# --- Analysis Logic ---

def analyze_command(path: str, exclude: List[str]):
    stats = {
        "count_by_ext": defaultdict(int),
        "size_by_ext": defaultdict(int),
        "all_files": [], # Store for top 10 and duplicates
        "hashes": defaultdict(list),
        "total_age_seconds": 0,
        "file_count_for_age": 0,
        "total_size": 0
    }

    now = time.time()

    for file_info in scan_directory(path, exclude):
        ext = file_info['ext']
        size = file_info['size']
        mtime = file_info['mtime']
        abs_path = file_info['abs_path']
        rel_path = file_info['rel_path']

        # Counts & Sizes
        stats["count_by_ext"][ext] += 1
        stats["size_by_ext"][ext] += size
        stats["total_size"] += size

        # Age
        age = now - mtime
        stats["total_age_seconds"] += age
        stats["file_count_for_age"] += 1

        # Store for Top 10
        stats["all_files"].append((rel_path, size))

        # Hashing for duplicates (only if size > 0 to save time, optional optimization)
        # To be thorough, we hash everything non-empty. 
        # For very large datasets, we might group by size first, then hash.
        # Here we hash directly but warn if too many files.
        if size > 0:
            f_hash = get_file_hash(abs_path)
            if f_hash:
                stats["hashes"][f_hash].append(rel_path)

    # Process Results
    # 1. Top 10 Largest
    stats["all_files"].sort(key=lambda x: x[1], reverse=True)
    top_10 = stats["all_files"][:10]

    # 2. Duplicates
    duplicates = {h: paths for h, paths in stats["hashes"].items() if len(paths) > 1}

    # 3. Avg Age
    avg_age = 0
    if stats["file_count_for_age"] > 0:
        avg_age = stats["total_age_seconds"] / stats["file_count_for_age"]

    result = {
        "summary": {
            "total_files": sum(stats["count_by_ext"].values()),
            "total_size": stats["total_size"],
            "average_age_seconds": avg_age
        },
        "by_extension": [
            {"extension": k, "count": v, "size": stats["size_by_ext"][k]} 
            for k, v in stats["count_by_ext"].items()
        ],
        "largest_files": [{"path": p, "size": s} for p, s in top_10],
        "duplicates": [
            {"hash": h, "files": paths} for h, paths in duplicates.items()
        ]
    }

    return result

# --- Comparison Logic ---

def compare_command(path1: str, path2: str, exclude: List[str]):
    def get_dir_map(root: str):
        """Returns map: relative_path -> {hash, size, mtime}"""
        file_map = {}
        for info in scan_directory(root, exclude, show_progress=False):
            # We need hash for content comparison
            h = get_file_hash(info['abs_path']) if info['size'] > 0 else "empty"
            file_map[info['rel_path']] = {
                "hash": h,
                "size": info['size'],
                "mtime": info['mtime']
            }
        return file_map

    print(c_cyan("Indexing first directory..."), file=sys.stderr)
    map1 = get_dir_map(path1)

    print(c_cyan("Indexing second directory..."), file=sys.stderr)
    map2 = get_dir_map(path2)

    keys1 = set(map1.keys())
    keys2 = set(map2.keys())

    only_in_1 = sorted(list(keys1 - keys2))
    only_in_2 = sorted(list(keys2 - keys1))
    common = keys1 & keys2

    modified = []
    for k in common:
        if map1[k]['hash'] != map2[k]['hash']:
            modified.append({
                "path": k,
                "size_1": map1[k]['size'],
                "size_2": map2[k]['size']
            })

    result = {
        "only_in_first": only_in_1,
        "only_in_second": only_in_2,
        "modified": modified,
        "summary": {
            "unique_to_1_count": len(only_in_1),
            "unique_to_2_count": len(only_in_2),
            "modified_count": len(modified),
            "identical_count": len(common) - len(modified)
        }
    }
    return result

# --- Output Formatters ---

def output_json(data: Any):
    print(json.dumps(data, indent=2))

def output_csv(data: Any, command: str):
    output = io.StringIO()

    if command == "analyze":
        writer = csv.writer(output)
        writer.writerow(["Section", "Extension", "Count", "Size", "Path", "Hash", "Note"])

        # Extensions
        for item in data.get("by_extension", []):
            writer.writerow(["By Extension", item['extension'], item['count'], item['size'], "", "", ""])

        # Top 10
        for item in data.get("largest_files", []):
            writer.writerow(["Top 10", "", "", "", item['path'], "", format_size(item['size'])])

        # Duplicates
        for item in data.get("duplicates", []):
            for f in item['files']:
