"""
fstats - File Statistics CLI Tool
Analyze and compare directory structures
"""

import argparse
import hashlib
import json
import os
import sys
import time
from collections import defaultdict
from datetime import datetime
from fnmatch import fnmatch
from pathlib import Path
from typing import Dict, List, Set, Tuple, Optional


# Color support detection and ANSI codes
def supports_color() -> bool:
    """Check if terminal supports color output."""
    if not hasattr(sys.stdout, 'isatty'):
        return False
    if not sys.stdout.isatty():
        return False
    if os.environ.get('TERM') == 'dumb':
        return False
    return True


USE_COLOR = supports_color()


class Colors:
    """ANSI color codes."""
    RESET = '\033[0m' if USE_COLOR else ''
    BOLD = '\033[1m' if USE_COLOR else ''
    RED = '\033[91m' if USE_COLOR else ''
    GREEN = '\033[92m' if USE_COLOR else ''
    YELLOW = '\033[93m' if USE_COLOR else ''
    BLUE = '\033[94m' if USE_COLOR else ''
    MAGENTA = '\033[95m' if USE_COLOR else ''
    CYAN = '\033[96m' if USE_COLOR else ''


def colorize(text: str, color: str) -> str:
    """Apply color to text."""
    return f"{color}{text}{Colors.RESET}"


def format_size(size_bytes: int) -> str:
    """Format bytes to human-readable size."""
    for unit in ['B', 'KB', 'MB', 'GB', 'TB']:
        if size_bytes < 1024.0:
            return f"{size_bytes:.2f} {unit}"
        size_bytes /= 1024.0
    return f"{size_bytes:.2f} PB"


def calculate_file_hash(filepath: Path, chunk_size: int = 8192) -> str:
    """Calculate MD5 hash of a file."""
    hasher = hashlib.md5()
    try:
        with open(filepath, 'rb') as f:
            while chunk := f.read(chunk_size):
                hasher.update(chunk)
        return hasher.hexdigest()
    except (IOError, OSError):
        return ""


class ProgressIndicator:
    """Simple progress indicator for file operations."""

    def __init__(self, enabled: bool = True):
        self.enabled = enabled and USE_COLOR
        self.count = 0
        self.last_update = 0

    def update(self, message: str = ""):
        """Update progress indicator."""
        if not self.enabled:
            return

        self.count += 1
        current_time = time.time()

        # Update every 0.1 seconds
        if current_time - self.last_update > 0.1:
            spinner = ['⠋', '⠙', '⠹', '⠸', '⠼', '⠴', '⠦', '⠧', '⠇', '⠏']
            idx = self.count % len(spinner)
            sys.stderr.write(f'\r{spinner[idx]} {message} ({self.count} files)')
            sys.stderr.flush()
            self.last_update = current_time

    def finish(self):
        """Clear progress indicator."""
        if self.enabled:
            sys.stderr.write('\r' + ' ' * 80 + '\r')
            sys.stderr.flush()


class FileStats:
    """Container for file statistics."""

    def __init__(self):
        self.count_by_ext: Dict[str, int] = defaultdict(int)
        self.size_by_ext: Dict[str, int] = defaultdict(int)
        self.largest_files: List[Tuple[str, int]] = []
        self.duplicates: Dict[str, List[str]] = defaultdict(list)
        self.file_ages: List[float] = []
        self.total_files = 0
        self.total_size = 0


def should_exclude(path: Path, exclude_patterns: List[str]) -> bool:
    """Check if path matches any exclude pattern."""
    path_str = str(path)
    for pattern in exclude_patterns:
        if fnmatch(path_str, pattern) or fnmatch(path.name, pattern):
            return True
    return False


def analyze_directory(path: Path, exclude_patterns: List[str] = None) -> FileStats:
    """Recursively analyze a directory and gather statistics."""
    if exclude_patterns is None:
        exclude_patterns = []

    stats = FileStats()
    progress = ProgressIndicator()
    file_hashes: Dict[str, List[str]] = defaultdict(list)
    all_files: List[Tuple[str, int]] = []

    try:
        for root, dirs, files in os.walk(path):
            root_path = Path(root)

            # Filter excluded directories
            dirs[:] = [d for d in dirs if not should_exclude(root_path / d, exclude_patterns)]

            for filename in files:
                filepath = root_path / filename

                if should_exclude(filepath, exclude_patterns):
                    continue

                progress.update(f"Analyzing {filepath.name}")

                try:
                    file_stat = filepath.stat()
                    file_size = file_stat.st_size
                    file_mtime = file_stat.st_mtime

                    # Extension statistics
                    ext = filepath.suffix.lower() or '(no extension)'
                    stats.count_by_ext[ext] += 1
                    stats.size_by_ext[ext] += file_size

                    # Track all files for largest files
                    all_files.append((str(filepath), file_size))

                    # File age
                    age_days = (time.time() - file_mtime) / 86400
                    stats.file_ages.append(age_days)

                    # Calculate hash for duplicate detection
                    file_hash = calculate_file_hash(filepath)
                    if file_hash:
                        file_hashes[file_hash].append(str(filepath))

                    stats.total_files += 1
                    stats.total_size += file_size

                except (OSError, IOError) as e:
                    print(f"Warning: Could not access {filepath}: {e}", file=sys.stderr)
                    continue

        progress.finish()

        # Find largest files
        all_files.sort(key=lambda x: x[1], reverse=True)
        stats.largest_files = all_files[:10]

        # Find duplicates (files with same hash)
        stats.duplicates = {h: files for h, files in file_hashes.items() if len(files) > 1}

    except Exception as e:
        progress.finish()
        raise e

    return stats


