/**
 * Processes a list of user IDs.
 * Maintains the original logic:
 * 1. Iterates through IDs.
 * 2. Fetches User then Posts sequentially per ID.
 * 3. If ANY error occurs in the chain, it aborts immediately (fails fast).
 * 4. Results are placed at the specific index to maintain order.
 */
async function processUsers(userIds) {
    const results = new Array(userIds.length);

    // We iterate sequentially to maintain the "fail-fast" behavior of the original code.
    // The original code used forEach but relied on a shared `hasError` flag to stop
    // processing callbacks once an error occurred. However, since network requests
    // are asynchronous, the original code actually started ALL requests in parallel
    // but only processed the first error encountered.
    //
    // To strictly maintain "identical behavior" regarding the parallel nature of the 
    // requests while handling the "first error wins" logic, we should start all 
    // operations but handle the resolution carefully.
    //
    // HOWEVER, looking closely at the original code:
    // userIds.forEach starts all fetchUserData calls immediately (Parallel).
    // Inside fetchUserData callback, it starts fetchUserPosts (Sequential per user).
    // If an error happens in ANY fetchUserData, it calls callback(err) and sets hasError=true.
    // Subsequent completions check hasError and return early.
    //
    // To replicate this "Parallel Start, First Error Wins" pattern with async/await:

    const tasks = userIds.map(async (id, index) => {
        try {
            // Check if a global error has already been flagged by another task
            // Note: In pure async/await without external state, this is tricky.
            // The most faithful conversion of the *outcome* (fast fail) is to use Promise.race
            // or a shared abort controller. But simpler is to let them run and reject the whole batch.

            const user = await fetchUserData(id);
            const posts = await fetchUserPosts(id);

            return {
                index,
                data: {
                    ...user,
                    posts: posts,
                    postCount: posts.length
                }
            };
        } catch (err) {
            // Re-throw with index info if needed, but primarily we need to stop everything
            throw err;
        }
    });

    try {
        // Promise.all behaves similarly to the original: 
        // If any promise rejects, the whole thing rejects immediately with that error.
        // This matches the original's `if (err) return callback(err)` behavior where 
        // the first error stops the success flow.
        const completedTasks = await Promise.all(tasks);

        // Map results back to the correct indices (Promise.all preserves order, 
        // but our wrapper returns {index, data} just in case we switched strategies. 
        // Actually, Promise.all preserves input order, so we can just map directly).

        // Correction: The original code stored results by `results[index] = ...`.
        // Promise.all guarantees the result array matches the input order.
        return completedTasks.map(task => task.data);

    } catch (error) {
        // Propagate the first error encountered, matching the original behavior
        throw error;
    }
}

