}

async function fetchUserData(userId) {
    const url = `https://jsonplaceholder.typicode.com/users/${userId}`;
    try {
        return await httpsGet(url);
    } catch (e) {
        throw e;
    }
}

async function fetchUserPosts(userId) {
    const url = `https://jsonplaceholder.typicode.com/users/${userId}/posts`;
    try {
        const posts = await httpsGet(url);
        return posts;
    } catch (e) {
        // Maintain the specific error message from original
        if (e.message === 'Failed to parse response') {
            throw new Error('Failed to parse posts');
        }
        throw e;
    }
}

async function processUsers(userIds) {
    // Fetch all users in parallel
    const userPromises = userIds.map(async (id, index) => {
        const user = await fetchUserData(id);
        const posts = await fetchUserPosts(id);
        return {
            ...user,
            posts: posts,
            postCount: posts.length
        };
    });

    // Wait for all to complete, maintaining order
    const results = await Promise.all(userPromises);
    return results;
}

async function saveResults(results, filename) {
    const json = JSON.stringify(results, null, 2);

    try {
        await fs.writeFile(filename, json, 'utf8');
    } catch (err) {
        throw new Error(`Write failed: ${err.message}`);
    }

    try {
        const stats = await fs.stat(filename);
        return { filename, size: stats.size, count: results.length };
    } catch (err) {
        throw new Error(`Stat failed: ${err.message}`);
    }
}

// Main execution
(async function main() {
    try {
        const results = await processUsers([1, 2, 3, 4, 5]);
        console.log(`Processed ${results.length} users`);

        const info = await saveResults(results, 'users.json');
        console.log(`Saved ${info.count} users to ${info.filename} (${info.size} bytes)`);
    } catch (err) {
        console.error('Processing failed:', err.message);
        process.exit(1);
    }
})();
```

**Key changes made:**

1. **Promisified `https.get`**: Created a `httpsGet()` utility function that wraps the callback-based `https.get` in a Promise, handling data streaming, parsing, and errors.

2. **Converted to async/await**: All functions now use `async/await` instead of callbacks:
   - `fetchUserData()` - returns a Promise
   - `fetchUserPosts()` - returns a Promise with specific error handling
   - `processUsers()` - uses `Promise.all()` to maintain parallel execution
   - `saveResults()` - uses `fs.promises` for file operations

3. **Maintained parallel pattern**: The original code fetched all users in parallel (via `forEach`). The new code uses `Promise.all()` with `map()` to achieve the same parallel execution while maintaining array order.

4. **Error propagation**: 
   - Try/catch blocks wrap error-prone operations
   - Specific error messages are preserved (e.g., "Failed to parse posts")
   - Errors bubble up naturally through the async chain

5. **Used `fs.promises`**: Replaced callback-based `fs.writeFile` and `fs.stat` with their promise-based equivalents.

6. **IIFE for main execution**: Wrapped the main execution in an async IIFE to use await at the top level.

The behavior is identical: users are fetched in parallel, posts are fetched sequentially for each user, results are saved, and errors cause the process to exit with code 1.

Here is a complete, single-file solution containing the generic `DataTable` component and a `Demo` usage section.

### Features Included:
1.  **Generic Typing:** Works with any data structure `T`.
2.  **Sorting:** Click headers to toggle Ascending/Descending.
3.  **Global Search:** Filters rows based on text matching any column.
4.  **Pagination:** Configurable rows per page (10, 25, 50) with Next/Prev controls.
5.  **Selection:** Checkboxes for individual rows, "Select All" for the current page, and a visual counter for selected items.
6.  **Styling:** Clean, modern UI using Tailwind CSS.

```tsx
import React, { useState, useMemo, useEffect } from 'react';

// --- Types ---

type SortDirection = 'asc' | 'desc';

interface SortConfig<T> {
  key: keyof T;
  direction: SortDirection;
}

interface Column<T> {
  key: keyof T;
  header: string;
  render?: (item: T) => React.ReactNode; // Optional custom renderer
  sortable?: boolean;
  className?: string;
}

interface DataTableProps<T> {
  data: T[];
  columns: Column<T>[];
  idKey: keyof T; // Key used for unique row identification (e.g., 'id')
}

// --- Icons (Inline SVGs to avoid dependencies) ---

const SortIcon = ({ direction }: { direction: SortDirection | null }) => {
  if (!direction) return <span className="w-4 h-4 ml-1 opacity-30">↕</span>;
  return (
    <span className="w-4 h-4 ml-1">
      {direction === 'asc' ? '↑' : '↓'}
    </span>
  );
};

const SearchIcon = () => (
  <svg className="w-5 h-5 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
  </svg>
);

// --- Component ---

function DataTable<T extends Record<string, any>>({ data, columns, idKey }: DataTableProps<T>) {
  // State
  const [sortConfig, setSortConfig] = useState<SortConfig<T> | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [currentPage, setCurrentPage] = useState(1);
  const [rowsPerPage, setRowsPerPage] = useState(10);
  const [selectedIds, setSelectedIds] = useState<Set<string | number>>(new Set());

  // 1. Filtering
  const filteredData = useMemo(() => {
    if (!searchTerm) return data;
    const lowerTerm = searchTerm.toLowerCase();
    return data.filter((item) =>
      columns.some((col) => {
        const value = item[col.key];
        return value?.toString().toLowerCase().includes(lowerTerm);
      })
    );
  }, [data, searchTerm, columns]);

  // 2. Sorting
  const sortedData = useMemo(() => {
    if (!sortConfig) return filteredData;

    return [...filteredData].sort((a, b) => {
      const aValue = a[sortConfig.key];
      const bValue = b[sortConfig.key];

      if (aValue < bValue) return sortConfig.direction === 'asc' ? -1 : 1;
      if (aValue > bValue) return sortConfig.direction === 'asc' ? 1 : -1;
      return 0;
    });
  }, [filteredData, sortConfig]);

  // 3. Pagination
  const totalPages = Math.ceil(sortedData.length / rowsPerPage);
  const paginatedData = useMemo(() => {
    const start = (currentPage - 1) * rowsPerPage;
    return sortedData.slice(start, start + rowsPerPage);
  }, [sortedData, currentPage, rowsPerPage]);

  // Reset page when search changes
  useEffect(() => {
    setCurrentPage(1);
  }, [searchTerm, rowsPerPage]);

  // Handlers
  const handleSort = (key: keyof T) => {
    let direction: SortDirection = 'asc';
    if (sortConfig && sortConfig.key === key && sortConfig.direction === 'asc') {
      direction = 'desc';
    }
    setSortConfig({ key, direction });
  };

  const toggleSelectAll = () => {
    const newSelected = new Set(selectedIds);
    const allSelectedOnPage = paginatedData.every((item) =>
      newSelected.has(item[idKey])
    );

    if (allSelectedOnPage) {
      // Deselect all on current page
      paginatedData.forEach((item) => newSelected.delete(item[idKey]));
    } else {
      // Select all on current page
      paginatedData.forEach((item) => newSelected.add(item[idKey]));
    }
    setSelectedIds(newSelected);
  };

  const toggleSelectRow = (id: string | number) => {
    const newSelected = new Set(selectedIds);
    if (newSelected.has(id)) {
      newSelected.delete(id);
    } else {
      newSelected.add(id);
    }
    setSelectedIds(newSelected);
  };

  const isAllSelected = paginatedData.length > 0 && paginatedData.every((item) => selectedIds.has(item[idKey]));
  const isIndeterminate = paginatedData.some((item) => selectedIds.has(item[idKey])) && !isAllSelected;

  return (
    <div className="w-full bg-white rounded-lg shadow border border-gray-200 overflow-hidden">
      {/* Toolbar */}
      <div className="p-4 border-b border-gray-200 flex flex-col sm:flex-row justify-between items-center gap-4">
        <div className="relative w-full sm:w-64">
          <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
            <SearchIcon />
          </div>
          <input
            type="text"
            placeholder="Search..."
            className="pl-10 pr-4 py-2 border border-gray-300 rounded-md w-full focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none transition"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>

        <div className="flex items-center gap-2">
          <span className="text-sm text-gray-600">Rows per page:</span>
          <select
            value={rowsPerPage}
            onChange={(e) => setRowsPerPage(Number(e.target.value))}
            className="border border-gray-300 rounded-md px-2 py-1 text-sm focus:ring-blue-500 focus:border-blue-500"
          >
            <option value={10}>10</option>
            <option value={25}>25</option>
            <option value={50}>50</option>
          </select>
        </div>
      </div>

      {/* Table */}
      <div className="overflow-x-auto">
        <table className="w-full text-left border-collapse">
          <thead>
            <tr className="bg-gray-50 text-gray-600 text-sm uppercase tracking-wider">
              <th className="p-4 border-b border-gray-200 w-12">
                <input
                  type="checkbox"
                  checked={isAllSelected}
                  ref={(input) => {
                    if (input) input.indeterminate = isIndeterminate;
                  }}
                  onChange={toggleSelectAll}
                  className="w-4 h-4 text-blue-600 rounded border-gray-300 focus:ring-blue-500"
                />
              </th>
              {columns.map((col) => (
                <th
                  key={col.key as string}
                  onClick={() => col.sortable !== false ? handleSort(col.key) : null}
                  className={`p-4 border-b border-gray-200 font-semibold ${col.sortable !== false ? 'cursor-pointer hover:bg-gray-100 select-none' : ''} ${col.className || ''}`}
                >
                  <div className="flex items-center">
                    {col.header}
                    {col.sortable !== false && <SortIcon direction={sortConfig?.key === col.key ? sortConfig.direction : null} />}
                  </div>
                </th>
              ))}
            </tr>
          </thead>
          <tbody className="divide-y divide-gray-200">
            {paginatedData.length > 0 ? (
              paginatedData.map((item) => {
                const itemId = item[idKey];
                const isSelected = selectedIds.has(itemId);
                return (
                  <tr
                    key={itemId as string}
                    className={`hover:bg-blue-50 transition-colors ${isSelected ? 'bg-blue-50' : 'bg-white'}`}
                  >
                    <td className="p-4">
                      <input
                        type="checkbox"
                        checked={isSelected}
                        onChange={() => toggleSelectRow(itemId)}
                        className="w-4 h-4 text-blue-600 rounded border-gray-300 focus:ring-blue-500"
                      />
                    </td>
                    {columns.map((col) => (
                      <td key={col.key as string} className={`p-4 text-sm text-gray-700 ${col.className || ''}`}>
                        {col.render ? col.render(item) : item[col.key]}
                      </td>
                    ))}
                  </tr>
                );
              })
            ) : (
              <tr>
                <td colSpan={columns.length + 1} className="p-8 text-center text-gray-500">
                  No results found.
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      {/* Footer / Pagination */}
      <div className="p-4 border-t border-gray-200 flex flex-col sm:flex-row justify-between items-center gap-4">
        <div className="text-sm text-gray-600">
          {selectedIds.size > 0 ? (
            <span className="text-blue-600 font-medium">{selectedIds.size} selected</span>
          ) : (
            <span>Showing <span className="font-medium">{paginatedData.length}</span> of <span className="font-medium">{sortedData.length}</span> entries</span>
          )}
        </div>

        <div className="flex items-center gap-2">
          <button
            onClick={() => setCurrentPage((p) => Math.max(1, p - 1))}
            disabled={currentPage === 1}
            className="px-3 py-1 border border-gray-300 rounded-md text-sm disabled:opacity-50 disabled:cursor-not-allowed hover:bg-gray-50"
          >
            Previous
          </button>
          <span className="text-sm text-gray-600 px-2">
            Page {currentPage} of {totalPages || 1}
          </span>
          <button
            onClick={() => setCurrentPage((p) => Math.min(totalPages, p + 1))}
            disabled={currentPage === totalPages || totalPages === 0}
            className="px-3 py-1 border border-gray-300 rounded-md text-sm disabled:opacity-50 disabled:cursor-not-allowed hover:bg-gray-50"
          >
            Next
          </button>
        </div>
      </div>
    </div>
  );
}

// --- Demo Usage ---

