# React TypeScript Data Table Component

## DataTable.tsx

```typescript
import React, { useState, useMemo, useCallback, useEffect } from 'react';

// ─── Types ───────────────────────────────────────────────────────────────────

type SortDirection = 'asc' | 'desc' | null;

interface ColumnDef<T> {
  key: keyof T & string;
  header: string;
  render?: (value: T[keyof T], row: T) => React.ReactNode;
  sortable?: boolean;
  searchable?: boolean;
}

interface DataTableProps<T extends Record<string, unknown>> {
  data: T[];
  columns: ColumnDef<T>[];
  pageSizeOptions?: number[];
  defaultPageSize?: number;
  rowKey: keyof T & string;
  onSelectionChange?: (selectedRows: T[]) => void;
}

interface SortState<T> {
  column: keyof T & string | null;
  direction: SortDirection;
}

// ─── Icons (inline SVGs to avoid dependencies) ──────────────────────────────

const ChevronUpIcon: React.FC<{ className?: string }> = ({ className }) => (
  <svg className={className} viewBox="0 0 20 20" fill="currentColor" width="16" height="16">
    <path fillRule="evenodd" d="M14.707 12.707a1 1 0 01-1.414 0L10 9.414l-3.293 3.293a1 1 0 01-1.414-1.414l4-4a1 1 0 011.414 0l4 4a1 1 0 010 1.414z" clipRule="evenodd" />
  </svg>
);

const ChevronDownIcon: React.FC<{ className?: string }> = ({ className }) => (
  <svg className={className} viewBox="0 0 20 20" fill="currentColor" width="16" height="16">
    <path fillRule="evenodd" d="M5.293 7.293a1 1 0 011.414 0L10 11.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z" clipRule="evenodd" />
  </svg>
);

const SearchIcon: React.FC<{ className?: string }> = ({ className }) => (
  <svg className={className} viewBox="0 0 20 20" fill="currentColor" width="20" height="20">
    <path fillRule="evenodd" d="M8 4a4 4 0 100 8 4 4 0 000-8zM2 8a6 6 0 1110.89 3.476l4.817 4.817a1 1 0 01-1.414 1.414l-4.816-4.816A6 6 0 012 8z" clipRule="evenodd" />
  </svg>
);

// ─── DataTable Component ─────────────────────────────────────────────────────

function DataTable<T extends Record<string, unknown>>({
  data,
  columns,
  pageSizeOptions = [10, 25, 50],
  defaultPageSize = 10,
  rowKey,
  onSelectionChange,
}: DataTableProps<T>): React.ReactElement {
  // ── State ────────────────────────────────────────────────────────────────

  const [searchQuery, setSearchQuery] = useState<string>('');
  const [sort, setSort] = useState<SortState<T>>({ column: null, direction: null });
  const [currentPage, setCurrentPage] = useState<number>(1);
  const [pageSize, setPageSize] = useState<number>(defaultPageSize);
  const [selectedKeys, setSelectedKeys] = useState<Set<string>>(new Set());

  // ── Derived: searchable column keys ──────────────────────────────────────

  const searchableKeys = useMemo(
    () =>
      columns
        .filter((col) => col.searchable !== false)
        .map((col) => col.key),
    [columns],
  );

  // ── Filtering ────────────────────────────────────────────────────────────

  const filteredData = useMemo(() => {
    if (!searchQuery.trim()) return data;
    const lowerQuery = searchQuery.toLowerCase();
    return data.filter((row) =>
      searchableKeys.some((key) => {
        const value = row[key];
        if (value == null) return false;
        return String(value).toLowerCase().includes(lowerQuery);
      }),
    );
  }, [data, searchQuery, searchableKeys]);

  // ── Sorting ──────────────────────────────────────────────────────────────

  const sortedData = useMemo(() => {
    if (!sort.column || !sort.direction) return filteredData;
    const { column, direction } = sort;
    return [...filteredData].sort((a, b) => {
      const aVal = a[column];
      const bVal = b[column];

      if (aVal == null && bVal == null) return 0;
      if (aVal == null) return direction === 'asc' ? -1 : 1;
      if (bVal == null) return direction === 'asc' ? 1 : -1;

      let comparison = 0;
      if (typeof aVal === 'number' && typeof bVal === 'number') {
        comparison = aVal - bVal;
      } else if (aVal instanceof Date && bVal instanceof Date) {
        comparison = aVal.getTime() - bVal.getTime();
      } else {
        comparison = String(aVal).localeCompare(String(bVal));
      }

      return direction === 'asc' ? comparison : -comparison;
    });
  }, [filteredData, sort]);

  // ── Pagination ───────────────────────────────────────────────────────────

  const totalPages = Math.max(1, Math.ceil(sortedData.length / pageSize));

  // Reset to page 1 when filters/page-size change
  useEffect(() => {
    setCurrentPage(1);
  }, [searchQuery, pageSize]);

  // Clamp current page
  useEffect(() => {
    if (currentPage > totalPages) {
      setCurrentPage(totalPages);
    }
  }, [totalPages, currentPage]);

  const paginatedData = useMemo(() => {
    const start = (currentPage - 1) * pageSize;
    return sortedData.slice(start, start + pageSize);
  }, [sortedData, currentPage, pageSize]);

  // ── Selection helpers ────────────────────────────────────────────────────

  const allPageKeys = useMemo(
    () => paginatedData.map((row) => String(row[rowKey])),
    [paginatedData, rowKey],
  );

  const allPageSelected =
    allPageKeys.length > 0 && allPageKeys.every((k) => selectedKeys.has(k));
  const somePageSelected =
    !allPageSelected && allPageKeys.some((k) => selectedKeys.has(k));

  const toggleSelectAll = useCallback(() => {
    setSelectedKeys((prev) => {
      const next = new Set(prev);
      if (allPageSelected) {
        allPageKeys.forEach((k) => next.delete(k));
      } else {
        allPageKeys.forEach((k) => next.add(k));
      }
      return next;
    });
  }, [allPageKeys, allPageSelected]);

  const toggleSelectRow = useCallback((key: string) => {
    setSelectedKeys((prev) => {
      const next = new Set(prev);
      if (next.has(key)) {
        next.delete(key);
      } else {
        next.add(key);
      }
      return next;
    });
  }, []);

  // Notify parent of selection changes
  useEffect(() => {
    if (onSelectionChange) {
      const selectedRows = data.filter((row) =>
        selectedKeys.has(String(row[rowKey])),
      );
      onSelectionChange(selectedRows);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selectedKeys]);

  // ── Sort handler ─────────────────────────────────────────────────────────

  const handleSort = useCallback(
    (columnKey: keyof T & string) => {
      setSort((prev) => {
        if (prev.column !== columnKey) {
          return { column: columnKey, direction: 'asc' };
        }
        if (prev.direction === 'asc') {
          return { column: columnKey, direction: 'desc' };
        }
        // Reset sort
        return { column: null, direction: null };
      });
    },
    [],
  );

  // ── Pagination range for page buttons ────────────────────────────────────

  const pageNumbers = useMemo(() => {
    const pages: (number | '...')[] = [];
    const maxVisible = 7;

    if (totalPages <= maxVisible) {
      for (let i = 1; i <= totalPages; i++) pages.push(i);
    } else {
      pages.push(1);
      if (currentPage > 3) pages.push('...');

      const start = Math.max(2, currentPage - 1);
      const end = Math.min(totalPages - 1, currentPage + 1);
      for (let i = start; i <= end; i++) pages.push(i);

      if (currentPage < totalPages - 2) pages.push('...');
      pages.push(totalPages);
    }

    return pages;
  }, [totalPages, currentPage]);

  // ── Render ───────────────────────────────────────────────────────────────

  const startRow = sortedData.length === 0 ? 0 : (currentPage - 1) * pageSize + 1;
  const endRow = Math.min(currentPage * pageSize, sortedData.length);

  return (
    <div className="w-full bg-white rounded-xl shadow-lg border border-gray-200 overflow-hidden">
      {/* ── Toolbar ─────────────────────────────────────────────────────── */}
      <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-3 p-4 border-b border-gray-200 bg-gray-50/60">
        {/* Search */}
        <div className="relative w-full sm:w-80">
          <SearchIcon className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" />
          <input
            type="text"
            placeholder="Search across all columns…"
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-full pl-10 pr-4 py-2 text-sm border border-gray-300 rounded-lg
                       focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500
                       placeholder-gray-400 transition"
          />
        </div>

        <div className="flex items-center gap-4 w-full sm:w-auto justify-between sm:justify-end">
          {/* Selected count */}
          {selectedKeys.size > 0 && (
            <div className="flex items-center gap-2 px-3 py-1.5 bg-indigo-50 text-indigo-700 rounded-lg text-sm font-medium">
              <span className="inline-flex items-center justify-center w-6 h-6 bg-indigo-600 text-white rounded-full text-xs font-bold">
                {selectedKeys.size}
              </span>
              selected
              <button
                onClick={() => setSelectedKeys(new Set())}
                className="ml-1 text-indigo-400 hover:text-indigo-700 transition"
                title="Clear selection"
              >
                ✕
              </button>
            </div>
          )}

          {/* Page size selector */}
          <div className="flex items-center gap-2 text-sm text-gray-600">
            <label htmlFor="pageSize" className="whitespace-nowrap">
              Rows:
            </label>
            <select
              id="pageSize"
              value={pageSize}
              onChange={(e) => setPageSize(Number(e.target.value))}
              className="border border-gray-300 rounded-lg px-2 py-1.5 text-sm
                         focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500
                         bg-white cursor-pointer transition"
            >
              {pageSizeOptions.map((size) => (
                <option key={size} value={size}>
                  {size}
                </option>
              ))}
            </select>
          </div>
        </div>
      </div>

      {/* ── Table ───────────────────────────────────────────────────────── */}
      <div className="overflow-x-auto">
        <table className="w-full text-sm">
          <thead>
            <tr className="bg-gray-50 border-b border-gray-200">
              {/* Select-all checkbox */}
              <th className="w-12 px-4 py-3">
                <input
                  type="checkbox"
                  checked={allPageSelected}
                  ref={(el) => {
                    if (el) el.indeterminate = somePageSelected;
                  }}
                  onChange={toggleSelectAll}
                  className="w-4 h-4 text-indigo-600 border-gray-300 rounded
                             focus:ring-indigo-500 focus:ring-2 cursor-pointer transition"
                />
              </th>

              {columns.map((col) => {
                const isSortable = col.sortable !== false;
                const isActive = sort.column === col.key;

                return (
                  <th
                    key={col.key}
                    className={`px-4 py-3 text-left text-xs font-semibold text-gray-500 uppercase tracking-wider
                      ${isSortable ? 'cursor-pointer select-none hover:text-gray-700 hover:bg-gray-100 transition-colors' : ''}`}
                    onClick={() => isSortable && handleSort(col.key)}
                  >
                    <div className="flex items-center gap-1">
                      <span>{col.header}</span>
                      {isSortable && (
                        <span className="flex flex-col -space-y-1">
                          <ChevronUpIcon
                            className={`${
                              isActive && sort.direction === 'asc'
                                ? 'text-indigo-600'
                                : 'text-gray-300'
                            } transition-colors`}
                          />
                          <ChevronDownIcon
                            className={`${
                              isActive && sort.direction === 'desc'
                                ? 'text-indigo-600'
                                : 'text-gray-300'
                            } transition-colors`}
                          />
                        </span>
                      )}
                    </div>
                  </th>
                );
              })}
            </tr>
          </thead>

          <tbody className="divide-y divide-gray-100">
            {paginatedData.length === 0 ? (
              <tr>
                <td
                  colSpan={columns.length + 1}
                  className="px-4 py-12 text-center text-gray-400"
                >
                  <div className="flex flex-col items-center gap-2">
                    <SearchIcon className="w-8 h-8 text-gray-300" />
                    <span className="text-base font-medium">No results found</span>
                    <span className="text-sm">Try adjusting your search query</span>
                  </div>
                </td>
              </tr>
            ) : (
              paginatedData.map((row, rowIndex) => {
                const key = String(row[rowKey]);
                const isSelected = selectedKeys.has(key);

                return (
                  <tr
                    key={key}
                    className={`transition-colors ${
                      isSelected
                        ? 'bg-indigo-50/60 hover:bg-indigo-50'
                        : rowIndex % 2 === 0
                        ? 'bg-white hover:bg-gray-50'
                        : 'bg-gray-50/30 hover:bg-gray-50'
                    }`}
                  >
                    <td className="w-12 px-4 py-3">
                      <input
                        type="checkbox"
                        checked={isSelected}
                        onChange={() => toggleSelectRow(key)}
                        className="w-4 h-4 text-indigo-600 border-gray-300 rounded
                                   focus:ring-indigo-500 focus:ring-2 cursor-pointer transition"
                      />
                    </td>
                    {columns.map((col) => (
                      <td key={col.key} className="px-4 py-3 text-gray-700 whitespace-nowrap">
                        {col.render
                          ? col.render(row[col.key], row)
                          : String(row[col.key] ?? '')}
                      </td>
                    ))}
                  </tr>
                );
              })
            )}
          </tbody>
        </table>
      </div>

      {/* ── Footer / Pagination ─────────────────────────────────────────── */}
      <div className="flex flex-col sm:flex-row items-center justify-between gap-3 px-4 py-3 border-t border-gray-200 bg-gray-50/60 text-sm text-gray-600">
        <span>
          Showing <span className="font-semibold text-gray-800">{startRow}</span>–
          <span className="font-semibold text-gray-800">{endRow}</span> of{' '}
          <span className="font-semibold text-gray-800">{sortedData.length}</span> results
        </span>

        <div className="flex items-center gap-1">
          {/* Previous */}
          <button
            disabled={currentPage === 1}
            onClick={() => setCurrentPage((p) => p - 1)}
            className="px-3 py-1.5 rounded-lg border border-gray-300 bg-white
                       hover:bg-gray-100 disabled:opacity-40 disabled:cursor-not-allowed
                       transition font-medium"
          >
            ← Prev
          </button>

          {/* Page numbers */}
          {pageNumbers.map((page, idx) =>
            page === '...' ? (
              <span key={`ellipsis-${idx}`} className="px-2 py-1 text-gray-400">
                …
              </span>
            ) : (
              <button
                key={page}
                onClick={() => setCurrentPage(page as number)}
                className={`px-3 py-1.5 rounded-lg border transition font-medium ${
                  currentPage === page
                    ? 'bg-indigo-600 text-white border-indigo-600 shadow-sm'
                    : 'border-gray-300 bg-white hover:bg-gray-100 text-gray-700'
                }`}
              >
                {page}
              </button>
            ),
          )}

          {/* Next */}
          <button
            disabled={currentPage === totalPages}
            onClick={() => setCurrentPage((p) => p + 1)}
            className="px-3 py-1.5 rounded-lg border border-gray-300 bg-white
                       hover:bg-gray-100 disabled:opacity-40 disabled:cursor-not-allowed
                       transition font-medium"
          >
            Next →
          </button>
        </div>
      </div>
    </div>
  );
}

export default DataTable;
```

