### 1. The Data Table Component (`src/components/DataTable.tsx`)

This file contains the core logic for the data table. It's generic and can accept any data type.

```typescript
// src/components/DataTable.tsx

import React, { useState, useMemo } from 'react';

// Define the shape of a column
export interface Column<T> {
  accessor: keyof T;
  header: string;
  sortable?: boolean;
  // Optional custom render function for a cell
  cell?: (item: T) => React.ReactNode;
}

// Define the props for the DataTable component
interface DataTableProps<T> {
  data: T[];
  columns: Column<T>[];
}

type SortDirection = 'ascending' | 'descending';

// The generic DataTable component
export function DataTable<T extends object>({ data, columns }: DataTableProps<T>) {
  const [searchTerm, setSearchTerm] = useState('');
  const [pageSize, setPageSize] = useState(10);
  const [currentPage, setCurrentPage] = useState(1);
  const [sortConfig, setSortConfig] = useState<{ key: keyof T; direction: SortDirection } | null>(null);
  const [selectedRows, setSelectedRows] = useState<Set<T>>(new Set());

  // Memoized data processing pipeline: filtering -> sorting -> pagination
  const processedData = useMemo(() => {
    let filteredData = [...data];

    // 1. Filtering
    if (searchTerm) {
      filteredData = filteredData.filter(item =>
        columns.some(column => {
          const value = item[column.accessor];
          return String(value).toLowerCase().includes(searchTerm.toLowerCase());
        })
      );
    }

    // 2. Sorting
    if (sortConfig !== null) {
      filteredData.sort((a, b) => {
        const aValue = a[sortConfig.key];
        const bValue = b[sortConfig.key];

        if (aValue === null || aValue === undefined) return 1;
        if (bValue === null || bValue === undefined) return -1;

        if (aValue < bValue) {
          return sortConfig.direction === 'ascending' ? -1 : 1;
        }
        if (aValue > bValue) {
          return sortConfig.direction === 'ascending' ? 1 : -1;
        }
        return 0;
      });
    }

    return filteredData;
  }, [data, searchTerm, sortConfig, columns]);

  const totalPages = Math.ceil(processedData.length / pageSize);

  // 3. Pagination
  const paginatedData = useMemo(() => {
    const startIndex = (currentPage - 1) * pageSize;
    return processedData.slice(startIndex, startIndex + pageSize);
  }, [processedData, currentPage, pageSize]);

  // Handler for sorting
  const requestSort = (key: keyof T) => {
    let direction: SortDirection = 'ascending';
    if (sortConfig && sortConfig.key === key && sortConfig.direction === 'ascending') {
      direction = 'descending';
    }
    setSortConfig({ key, direction });
  };

  // Handlers for row selection
  const handleSelectRow = (item: T) => {
    setSelectedRows(prevSelected => {
      const newSelected = new Set(prevSelected);
      if (newSelected.has(item)) {
        newSelected.delete(item);
      } else {
        newSelected.add(item);
      }
      return newSelected;
    });
  };

  const handleSelectAll = () => {
    if (selectedRows.size === paginatedData.length) {
      // Deselect all visible rows
      const newSelected = new Set(selectedRows);
      paginatedData.forEach(item => newSelected.delete(item));
      setSelectedRows(newSelected);
    } else {
      // Select all visible rows
      const newSelected = new Set(selectedRows);
      paginatedData.forEach(item => newSelected.add(item));
      setSelectedRows(newSelected);
    }
  };

  const isAllVisibleSelected = paginatedData.length > 0 && paginatedData.every(item => selectedRows.has(item));

  return (
    <div className="w-full overflow-x-auto">
      {/* Top Controls: Search, Page Size, and Selected Count */}
      <div className="flex flex-col sm:flex-row justify-between items-center mb-4 gap-4">
        <input
          type="text"
          placeholder="Search all columns..."
          value={searchTerm}
          onChange={e => {
            setSearchTerm(e.target.value);
            setCurrentPage(1); // Reset to first page on search
          }}
          className="w-full sm:w-1/3 px-3 py-2 border border-gray-300 rounded-md shadow-sm focus:outline-none focus:ring-indigo-500 focus:border-indigo-500"
        />
        <div className="flex items-center gap-4">
          {selectedRows.size > 0 && (
            <span className="text-sm font-medium text-gray-700">
              {selectedRows.size} selected
            </span>
          )}
          <select
            value={pageSize}
            onChange={e => {
              setPageSize(Number(e.target.value));
              setCurrentPage(1); // Reset to first page on page size change
            }}
            className="px-3 py-2 border border-gray-300 rounded-md shadow-sm focus:outline-none focus:ring-indigo-500 focus:border-indigo-500"
          >
            <option value={10}>10 per page</option>
            <option value={25}>25 per page</option>
            <option value={50}>50 per page</option>
          </select>
        </div>
      </div>

      {/* Table */}
      <div className="border border-gray-200 rounded-lg shadow-sm">
        <table className="min-w-full divide-y divide-gray-200">
          <thead className="bg-gray-50">
            <tr>
              <th scope="col" className="p-4">
                <input
                  type="checkbox"
                  className="h-4 w-4 text-indigo-600 border-gray-300 rounded focus:ring-indigo-500"
                  checked={isAllVisibleSelected}
                  onChange={handleSelectAll}
                  aria-label="Select all items on this page"
                />
              </th>
              {columns.map(column => (
                <th
                  key={String(column.accessor)}
                  scope="col"
                  className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider"
                >
                  {column.sortable ? (
                    <button
                      onClick={() => requestSort(column.accessor)}
                      className="flex items-center gap-2 group"
                    >
                      {column.header}
                      <span className="opacity-0 group-hover:opacity-100 transition-opacity">
                        {sortConfig?.key === column.accessor
                          ? sortConfig.direction === 'ascending' ? '▲' : '▼'
                          : '↕'}
                      </span>
                    </button>
                  ) : (
                    column.header
                  )}
                </th>
              ))}
            </tr>
          </thead>
          <tbody className="bg-white divide-y divide-gray-200">
            {paginatedData.map((item, index) => (
              <tr key={index} className={`hover:bg-gray-50 ${selectedRows.has(item) ? 'bg-indigo-50' : ''}`}>
                <td className="p-4">
                  <input
                    type="checkbox"
                    className="h-4 w-4 text-indigo-600 border-gray-300 rounded focus:ring-indigo-500"
                    checked={selectedRows.has(item)}
                    onChange={() => handleSelectRow(item)}
                    aria-label={`Select row ${index + 1}`}
                  />
                </td>
                {columns.map(column => (
                  <td key={String(column.accessor)} className="px-6 py-4 whitespace-nowrap text-sm text-gray-700">
                    {column.cell ? column.cell(item) : String(item[column.accessor])}
                  </td>
                ))}
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* Bottom Controls: Pagination */}
      <div className="flex items-center justify-between mt-4">
        <span className="text-sm text-gray-700">
          Showing {paginatedData.length > 0 ? (currentPage - 1) * pageSize + 1 : 0} to{' '}
          {Math.min(currentPage * pageSize, processedData.length)} of {processedData.length} results
