class EventEmitter {
  constructor() {
    // FIX 1: Prevent prototype pollution by using Object.create(null)
    // Without this, event names like '__proto__', 'toString', or 'constructor'
    // could access or modify Object prototype properties, leading to security issues.
    this.listeners = Object.create(null);
  }

  on(event, callback) {
    if (!this.listeners[event]) {
      this.listeners[event] = [];
    }
    this.listeners[event].push(callback);
    return this; // Enables method chaining
  }

  off(event, callback) {
    if (this.listeners[event]) {
      // FIX 2: Use strict equality (!==) instead of loose equality (!=)
      // This ensures accurate function reference comparison.
      this.listeners[event] = this.listeners[event].filter(cb => cb !== callback);
    }
    // FIX 3: Return `this` for method chaining consistency with `on`
    return this;
  }

  emit(event, ...args) {
    if (this.listeners[event]) {
      // FIX 4: Copy the listeners array before iteration
      // Prevents issues if a callback modifies the listeners array during emission
      const listenersCopy = this.listeners[event].slice();
      listenersCopy.forEach(cb => cb(...args));
    }
  }

  once(event, callback) {
    // FIX 5: Create a wrapper that calls the callback once and then removes itself
    const wrapper = (...args) => {
      callback(...args);
      // FIX 6: Remove the wrapper function, not the original callback
      // The wrapper is what's actually registered, so it must be removed
      this.off(event, wrapper);
    };
    this.on(event, wrapper);
    // FIX 7: Return `this` for method chaining consistency
    return this;
  }
}

