```javascript
class EventEmitter {
  constructor() {
    // BUG 1: Using a plain object {} for listeners is vulnerable to prototype pollution.
    // An event named "__proto__" could modify Object.prototype.
    // FIX: Use Object.create(null) to create a dictionary-like object
    // that does not have a prototype. This prevents unintended access to
    // inherited properties like 'toString' or '__proto__'.
    this.listeners = Object.create(null);
  }

  on(event, callback) {
    if (!this.listeners[event]) {
      this.listeners[event] = [];
    }
    this.listeners[event].push(callback);
    return this;
  }

  off(event, callback) {
    if (this.listeners[event]) {
      this.listeners[event] = this.listeners[event].filter(cb => cb !== callback);
    }
    // BUG 2: The 'off' method did not return 'this', which breaks method chaining.
    // While not a functional error for the provided examples, it's an API design flaw.
    // FIX: Return 'this' to allow for a fluent API, consistent with the 'on' method.
    return this;
  }

  emit(event, ...args) {
    if (this.listeners[event]) {
      // BUG 3: Iterating directly over the listeners array is unsafe. If a listener
      // calls 'off', it modifies the array while it's being iterated,
      // which can cause other listeners in the same emit cycle to be skipped.
      // FIX: Create a shallow copy of the listeners array before iterating.
      // This ensures that the loop is not affected by modifications during the emit.
      const listeners = [...this.listeners[event]];
      listeners.forEach(cb => cb(...args));
    }
  }

  once(event, callback) {
    const wrapper = (...args) => {
      callback(...args);
      // BUG 4: The 'off' call was attempting to remove the original 'callback',
      // but the listener that was actually registered was the 'wrapper' function.
      // This meant the listener was never removed and would fire more than once.
      // FIX: Call 'off' with the 'wrapper' function itself to ensure it is removed
      // after the first execution.
      this.off(event, wrapper);
    };
    this.on(event, wrapper);
    // Returning 'this' for consistency, although not strictly a bug fix.
    return this;
  }
}

