from datetime import datetime
from typing import List, Dict, Any, Optional, Union

# Type alias for clarity
Record = Dict[str, Any]
Result = Union[List[Record], Dict[str, Any]]


def _filter_records(records: List[Record], user_id: Optional[str], flag: bool, mode: str) -> List[Record]:
    """Filter records based on status, user_id, score mode, and flag options."""
    results = []
    for item in records:
        # Original behavior: Access keys directly to preserve KeyError behavior
        if item["status"] != "active":
            continue

        if user_id is not None:
            if item["user_id"] == user_id:
                if flag:
                    item["flagged"] = True  # Side effect: modifies original data
                results.append(item)
        else:
            score = item["score"]
            if mode == "strict":
                if score >= 80:
                    results.append(item)
            elif mode == "lenient":
                if score >= 50:
                    results.append(item)
            else:  # "default"
                results.append(item)
    return results


def _transform_records(records: List[Record], flag: bool) -> List[Record]:
    """Transform records into a new structure with computed fields."""
    results = []
    for item in records:
        new_record = {
            "id": item["user_id"],
            "name": f"{item['first_name']} {item['last_name']}",
            "email": item["email"].lower().strip(),
        }

        score = item["score"]
        if score >= 90:
            new_record["tier"] = "gold"
        elif score >= 70:
            new_record["tier"] = "silver"
        elif score >= 50:
            new_record["tier"] = "bronze"
        else:
            new_record["tier"] = "basic"

        if flag:
            # Maintain identical behavior: timestamp generated per item
            new_record["processed_at"] = datetime.now().isoformat()

        results.append(new_record)
    return results


def _aggregate_records(records: List[Record]) -> Dict[str, Any]:
    """Aggregate records by department with statistics."""
    totals = {}
    for item in records:
        dept = item["department"]
        if dept not in totals:
            totals[dept] = {"count": 0, "total_score": 0, "active": 0}

        totals[dept]["count"] += 1
        totals[dept]["total_score"] += item["score"]
        if item["status"] == "active":
            totals[dept]["active"] += 1

    for dept in totals:
        totals[dept]["avg_score"] = round(
            totals[dept]["total_score"] / totals[dept]["count"], 2
        )

    return totals


def process(
    data: List[Record],
    operation: str,
    user_id: Optional[str] = None,
    flag: bool = False,
    mode: str = "default",
) -> Result:
    """
    Process a list of data records based on the specified operation type.

    Args:
        data: List of dictionaries containing record data.
        operation: Type of operation ('filter', 'transform', 'aggregate').
        user_id: Optional user ID for filtering.
        flag: Boolean flag for additional processing logic.
        mode: Filtering mode ('default', 'strict', 'lenient').

    Returns:
        Processed data (List or Dict depending on operation).
    """
    if operation == "filter":
        return _filter_records(data, user_id, flag, mode)
    elif operation == "transform":
        return _transform_records(data, flag)
    elif operation == "aggregate":
        return _aggregate_records(data)
    else:
        # Original behavior: returns empty list if operation type is unknown
        return []
```

### Explanation of Changes

1.  **Separation of Concerns:** The monolithic `process` function was split into three private helper functions (`_filter_records`, `_transform_records`, `_aggregate_records`). This makes each logic branch easier to read, test, and maintain.
2.  **Readable Naming:** Variable names were updated from single letters (`t`, `u`, `m`, `r`, `i`, `d`, `k`) to descriptive names (`operation`, `user_id`, `mode`, `results`, `item`, `new_record`, `dept`).
3.  **Pythonic Iteration:** Replaced `range(len(data))` indexing with direct iteration (`for item in data`), which is cleaner and slightly more efficient.
4.  **Import Management:** Moved the `datetime` import to the top of the file instead of using `__import__` inside the loop. The timestamp generation call remains inside the loop to preserve the original behavior of generating a unique timestamp per record.
5.  **Type Hinting:** Added type hints (`List`, `Dict`, `Optional`, etc.) to clarify expected input and output structures.
6.  **Behavior Preservation:**
    *   **Side Effects:** The refactored filter function still modifies the original input dictionary (`item["flagged"] = True`) when `flag` is True, matching the original side effect.
    *   **Error Handling:** Direct dictionary access (e.g., `item["status"]`) was kept instead of using `.get()`, ensuring `KeyError`s are raised exactly as they would be in the original code if keys are missing.
    *   **Return Types:** The function maintains the dynamic return type (List for filter/transform, Dict for aggregate, empty List for unknown operations).

