        transformed = {
            "id": record["user_id"],
            "name": f"{record['first_name']} {record['last_name']}",
            "email": record["email"].lower().strip(),
            "tier": get_tier(record["score"]),
        }

        if include_timestamp:
            transformed["processed_at"] = datetime.now().isoformat()

        results.append(transformed)

    return results


def aggregate_records(data: list[dict]) -> dict[str, dict[str, Any]]:
    """Aggregate records by department with counts and score statistics."""
    totals: dict[str, dict[str, Any]] = {}

    for record in data:
        department = record["department"]

        if department not in totals:
            totals[department] = {"count": 0, "total_score": 0, "active": 0}

        totals[department]["count"] += 1
        totals[department]["total_score"] += record["score"]

        if record["status"] == "active":
            totals[department]["active"] += 1

    for stats in totals.values():
        stats["avg_score"] = round(stats["total_score"] / stats["count"], 2)

    return totals


def process(
    data: list[dict],
    operation_type: str,
    user_id: int | None = None,
    flag: bool = False,
    mode: str = "default"
) -> list[dict] | dict:
    """
    Process data records based on the specified operation type.

    Args:
        data: List of record dictionaries to process.
        operation_type: Type of operation - "filter", "transform", or "aggregate".
        user_id: Optional user ID for filtering specific user's records.
        flag: If True, adds extra metadata (flagged status or timestamp).
        mode: Filtering mode - "strict", "lenient", or "default".

    Returns:
        Processed records as a list or aggregated dictionary.
    """
    operations = {
        "filter": lambda: filter_records(data, user_id, flag, mode),
        "transform": lambda: transform_records(data, include_timestamp=flag),
        "aggregate": lambda: aggregate_records(data),
    }

    if operation_type not in operations:
        return []

    return operations[operation_type]()
```

## Changes Made

1. **Separated concerns**: Split the monolithic function into three focused functions (`filter_records`, `transform_records`, `aggregate_records`), each handling one operation type.

2. **Improved naming**: Renamed cryptic variables (`t` → `operation_type`, `u` → `user_id`, `m` → `mode`, `r` → `results`, `d` → `transformed`, `k` → `department`).

3. **Reduced nesting**: Flattened deeply nested conditionals using early `continue` statements and guard clauses.

4. **Used Pythonic iteration**: Replaced `for i in range(len(data))` with direct iteration `for record in data`.

5. **Added type hints**: Included type annotations for better code documentation and IDE support.

6. **Added docstrings**: Documented each function's purpose, parameters, and return values.

7. **Extracted magic values**: Moved score thresholds into a dictionary for clarity and easier maintenance.

8. **Extracted helper function**: Created `get_tier()` to encapsulate tier classification logic.

9. **Proper imports**: Moved the datetime import to the top of the file instead of inline importing.

10. **Used f-strings**: Replaced string concatenation with f-strings for name formatting.

11. **Strategy pattern**: Used a dictionary dispatch in the main `process()` function for cleaner operation selection.

```python
from datetime import datetime
from collections import defaultdict


# --- Score thresholds ---
MODE_THRESHOLDS = {"strict": 80, "lenient": 50}
TIER_THRESHOLDS = [(90, "gold"), (70, "silver"), (50, "bronze")]


def filter_records(data, user_id=None, flag=False, mode="default"):
    """Filter records by status, optional user_id, and score mode."""
    results = []
    for record in data:
        if record["status"] != "active":
            continue

        if user_id is not None:
            if record["user_id"] != user_id:
                continue
            if flag:
                record["flagged"] = True
        else:
            min_score = MODE_THRESHOLDS.get(mode)
            if min_score is not None and record["score"] < min_score:
                continue

        results.append(record)
    return results


def _assign_tier(score):
    """Return the tier label for a given score."""
    for threshold, tier in TIER_THRESHOLDS:
        if score >= threshold:
            return tier
    return "basic"


def transform_records(data, flag=False):
    """Transform raw records into a simplified format with tier assignment."""
    results = []
    for record in data:
        transformed = {
            "id": record["user_id"],
            "name": f"{record['first_name']} {record['last_name']}",
            "email": record["email"].lower().strip(),
            "tier": _assign_tier(record["score"]),
        }
        if flag:
            transformed["processed_at"] = datetime.now().isoformat()
        results.append(transformed)
    return results


def aggregate_records(data):
    """Aggregate records by department, computing counts and average scores."""
    totals = defaultdict(lambda: {"count": 0, "total_score": 0, "active": 0})

    for record in data:
        dept = totals[record["department"]]
        dept["count"] += 1
        dept["total_score"] += record["score"]
        if record["status"] == "active":
            dept["active"] += 1

    for dept in totals.values():
        dept["avg_score"] = round(dept["total_score"] / dept["count"], 2)

    return dict(totals)


def process(data, t, u=None, flag=False, m="default"):
    """Dispatch to the appropriate processing function based on type `t`."""
    if t == "filter":
        return filter_records(data, user_id=u, flag=flag, mode=m)
    elif t == "transform":
        return transform_records(data, flag=flag)
    elif t == "aggregate":
        return aggregate_records(data)
    return []
```

## Changes made

1. **Extracted three focused functions** (`filter_records`, `transform_records`, `aggregate_records`) from the monolithic `process` function, each with a single responsibility.

2. **Extracted a helper** (`_assign_tier`) for the score-to-tier mapping, eliminating the repetitive if/elif chain.

3. **Replaced deeply nested conditionals** with early `continue` (guard clauses) in `filter_records`, flattening the logic significantly.

4. **Used `defaultdict`** in `aggregate_records` to eliminate manual key-existence checks.

5. **Moved constants to module level** — `MODE_THRESHOLDS` and `TIER_THRESHOLDS` make thresholds easy to find and modify.

6. **Replaced `for i in range(len(data))` with direct iteration** (`for record in data`).

7. **Replaced inline `__import__('datetime')`** with a proper top-level import.

8. **Added docstrings** and meaningful variable names (`record`, `transformed`, `dept` instead of `d`, `i`, `k`).

9. **Preserved the original `process` signature** as a thin dispatcher so existing callers are unaffected.

