This server handles connection state, room management, message history slicing, and broadcasting.

```javascript
const WebSocket = require('ws');

const PORT = 8080;
const wss = new WebSocket.Server({ port: PORT });

// In-memory storage
// Structure: { 'roomName': [ {type, user, content, timestamp}, ... ] }
const roomHistory = {}; 
// Structure: Map<WebSocket, { nickname: string, room: string | null }>
const clients = new Map();

console.log(`WebSocket server running on ws://localhost:${PORT}`);

// Helper: Send JSON to a specific socket
const send = (ws, data) => {
    if (ws.readyState === WebSocket.OPEN) {
        ws.send(JSON.stringify(data));
    }
};

// Helper: Broadcast to everyone in a specific room
const broadcastToRoom = (roomName, data, excludeWs = null) => {
    clients.forEach((clientData, ws) => {
        if (clientData.room === roomName && ws !== excludeWs) {
            send(ws, data);
        }
    });
};

// Helper: Add message to history (keep last 50)
const addToHistory = (roomName, message) => {
    if (!roomHistory[roomName]) roomHistory[roomName] = [];
    roomHistory[roomName].push(message);
    if (roomHistory[roomName].length > 50) {
        roomHistory[roomName] = roomHistory[roomName].slice(-50);
    }
};

wss.on('connection', (ws) => {
    // Initialize client state
    clients.set(ws, { nickname: `Guest_${Math.floor(Math.random() * 1000)}`, room: null });

    console.log('New connection');

    ws.on('message', (rawMessage) => {
        let data;
        try {
            data = JSON.parse(rawMessage);
        } catch (e) {
            return send(ws, { type: 'error', content: 'Invalid JSON' });
        }

        const client = clients.get(ws);

        switch (data.type) {
            case 'set_nickname':
                client.nickname = data.nickname || 'Anonymous';
                clients.set(ws, client); // Update map
                break;

            case 'join_room':
                const newRoom = data.room;
                const oldRoom = client.room;

                // Leave old room if exists
                if (oldRoom) {
                    broadcastToRoom(oldRoom, {
                        type: 'system',
                        content: `${client.nickname} has left the room.`,
                        timestamp: new Date().toISOString()
                    });
                }

                // Join new room
                client.room = newRoom;
                clients.set(ws, client);

                // Send existing history to the user
                const history = roomHistory[newRoom] || [];
                send(ws, { type: 'history', room: newRoom, messages: history });

                // Announce join to others
                broadcastToRoom(newRoom, {
                    type: 'system',
                    content: `${client.nickname} has joined the room.`,
                    timestamp: new Date().toISOString()
                }, ws);
                break;

            case 'chat_message':
                if (!client.room) return send(ws, { type: 'error', content: 'Join a room first' });

                const msgPayload = {
                    type: 'chat_message',
                    room: client.room,
                    user: client.nickname,
                    content: data.content,
                    timestamp: new Date().toISOString()
                };

                addToHistory(client.room, msgPayload);
                broadcastToRoom(client.room, msgPayload);
                break;

            case 'typing':
                if (client.room) {
                    broadcastToRoom(client.room, {
                        type: 'typing',
                        user: client.nickname,
                        isTyping: data.isTyping
                    }, ws);
                }
                break;
        }
    });

    ws.on('close', () => {
        const client = clients.get(ws);
        if (client && client.room) {
            broadcastToRoom(client.room, {
                type: 'system',
                content: `${client.nickname} has disconnected.`,
                timestamp: new Date().toISOString()
            });
        }
        clients.delete(ws);
        console.log('Connection closed');
    });
});
```

