        const ws = new WebSocket('ws://localhost:8080');
        const chatWindow = document.getElementById('chat-window');
        const typingIndicator = document.getElementById('typing-indicator');
        const msgInput = document.getElementById('message-input');
        const sendBtn = document.getElementById('send-btn');
        const statusSpan = document.getElementById('connection-status');

        let typingTimeout;
        let currentRoom = null;

        ws.onopen = () => {
            statusSpan.textContent = "Connected";
            statusSpan.style.color = "green";
            msgInput.disabled = false;
            sendBtn.disabled = false;
        };

        ws.onclose = () => {
            statusSpan.textContent = "Disconnected";
            statusSpan.style.color = "red";
            msgInput.disabled = true;
            sendBtn.disabled = true;
        };

        ws.onmessage = (event) => {
            const data = JSON.parse(event.data);
            handleServerMessage(data);
        };

        function handleServerMessage(data) {
            switch (data.type) {
                case 'history':
                    chatWindow.innerHTML = ''; // Clear current view
                    currentRoom = data.room;
                    data.messages.forEach(msg => appendMessage(msg));
                    break;

                case 'chat_message':
                    if (data.room === currentRoom) {
                        appendMessage(data);
                        scrollToBottom();
                    }
                    break;

                case 'system':
                    if (currentRoom) { // Only show system msgs if we are in a room context
                        appendSystemMessage(data.content);
                        scrollToBottom();
                    }
                    break;

                case 'typing':
                    if (data.room === currentRoom && data.user !== getNickname()) {
                        if (data.isTyping) {
                            typingIndicator.textContent = `${data.user} is typing...`;
                            // Clear existing timeout if user keeps typing
                            if (typingTimeout) clearTimeout(typingTimeout);
                            // Hide indicator after 2 seconds of no activity
                            typingTimeout = setTimeout(() => {
                                typingIndicator.textContent = '';
                            }, 2000);
                        } else {
                            typingIndicator.textContent = '';
                        }
                    }
                    break;

                case 'error':
                    alert('Server Error: ' + data.content);
                    break;
            }
        }

        function appendMessage(msg) {
            const div = document.createElement('div');
            div.className = 'message';
            const time = new Date(msg.timestamp).toLocaleTimeString();
            div.innerHTML = `<span class="meta">[${time}] <strong>${msg.user}:</strong></span> <span class="content">${escapeHtml(msg.content)}</span>`;
            chatWindow.appendChild(div);
        }

        function appendSystemMessage(text) {
            const div = document.createElement('div');
            div.className = 'message system';
            div.textContent = text;
            chatWindow.appendChild(div);
        }

        function scrollToBottom() {
            chatWindow.scrollTop = chatWindow.scrollHeight;
        }

        function getNickname() {
            return document.getElementById('nickname').value || 'Anonymous';
        }

        function joinRoom() {
            const room = document.getElementById('room-name').value;
            const nickname = getNickname();

            if (!room) return alert("Enter a room name");

            // Update local nickname first
            ws.send(JSON.stringify({ type: 'set_nickname', nickname: nickname }));

            // Join room
            ws.send(JSON.stringify({ type: 'join_room', room: room }));
        }

        function sendMessage() {
            const content = msgInput.value.trim();
            if (!content || !currentRoom) return;

            ws.send(JSON.stringify({
                type: 'chat_message',
                content: content
            }));

            msgInput.value = '';
            // Send stop typing signal
            ws.send(JSON.stringify({ type: 'typing', isTyping: false }));
        }

        function handleTyping() {
            if (!currentRoom) return;

            ws.send(JSON.stringify({ type: 'typing', isTyping: true }));

            if (typingTimeout) clearTimeout(typingTimeout);

            // If user stops typing for 1s, send false
            typingTimeout = setTimeout(() => {
                ws.send(JSON.stringify({ type: 'typing', isTyping: false }));
            }, 1000);
        }

        // Allow Enter key to send
        msgInput.addEventListener("keypress", function(event) {
            if (event.key === "Enter") sendMessage();
        });

        // Basic XSS prevention
        function escapeHtml(text) {
            const map = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#039;' };
            return text.replace(/[&<>"']/g, function(m) { return map[m]; });
        }
    </script>
