# WebSocket Chat Server with Node.js

A complete chat server implementation using only the `ws` package, featuring multiple rooms, nicknames, message history, typing indicators, and system messages.

## Server Code (server.js)

```javascript
const WebSocket = require('ws');
const http = require('http');
const fs = require('fs');
const path = require('path');

// Create HTTP server to serve the client
const server = http.createServer((req, res) => {
    if (req.url === '/' || req.url === '/index.html') {
        fs.readFile(path.join(__dirname, 'client.html'), (err, data) => {
            if (err) {
                res.writeHead(500);
                res.end('Error loading client');
                return;
            }
            res.writeHead(200, { 'Content-Type': 'text/html' });
            res.end(data);
        });
    } else {
        res.writeHead(404);
        res.end('Not found');
    }
});

// Create WebSocket server
const wss = new WebSocket.Server({ server });

// In-memory storage
const rooms = new Map(); // roomName -> Set of client IDs
const clients = new Map(); // clientId -> { ws, nickname, currentRoom, typingTimeout }
const messageHistory = new Map(); // roomName -> Array of messages (max 50)

const MAX_HISTORY = 50;

// Generate unique client ID
function generateClientId() {
    return `user_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
}

// Get or create room
function getRoom(roomName) {
    if (!rooms.has(roomName)) {
        rooms.set(roomName, new Set());
        messageHistory.set(roomName, []);
    }
    return rooms.get(roomName);
}

// Add message to room history
function addToHistory(roomName, message) {
    if (!messageHistory.has(roomName)) {
        messageHistory.set(roomName, []);
    }
    const history = messageHistory.get(roomName);
    history.push(message);
    if (history.length > MAX_HISTORY) {
        history.shift();
    }
}

// Create message object
function createMessage(type, room, user, content) {
    return {
        type,
        room,
        user,
        content,
        timestamp: new Date().toISOString()
    };
}

// Broadcast to room
function broadcastToRoom(roomName, message, excludeClientId = null) {
    const room = rooms.get(roomName);
    if (!room) return;

    const messageStr = JSON.stringify(message);
    room.forEach(clientId => {
        if (clientId !== excludeClientId) {
            const client = clients.get(clientId);
            if (client && client.ws.readyState === WebSocket.OPEN) {
                client.ws.send(messageStr);
            }
        }
    });
}

// Send to specific client
function sendToClient(clientId, message) {
    const client = clients.get(clientId);
    if (client && client.ws.readyState === WebSocket.OPEN) {
        client.ws.send(JSON.stringify(message));
    }
}

// Get users in room
function getRoomUsers(roomName) {
    const room = rooms.get(roomName);
    if (!room) return [];

    const users = [];
    room.forEach(clientId => {
        const client = clients.get(clientId);
        if (client) {
            users.push({
                id: clientId,
                nickname: client.nickname
            });
        }
    });
    return users;
}

// Handle client joining a room
function joinRoom(clientId, roomName) {
    const client = clients.get(clientId);
    if (!client) return;

    // Leave current room if in one
    if (client.currentRoom) {
        leaveRoom(clientId);
    }

    // Join new room
    const room = getRoom(roomName);
    room.add(clientId);
    client.currentRoom = roomName;

    // Send room history to client
    const history = messageHistory.get(roomName) || [];
    sendToClient(clientId, {
        type: 'history',
        room: roomName,
        messages: history
    });

    // Send user list to client
    sendToClient(clientId, {
        type: 'userList',
        room: roomName,
        users: getRoomUsers(roomName)
    });

    // Broadcast join message
    const joinMessage = createMessage('system', roomName, 'System', `${client.nickname} joined the room`);
    addToHistory(roomName, joinMessage);
    broadcastToRoom(roomName, joinMessage, clientId);

    // Confirm join to client
    sendToClient(clientId, {
        type: 'joinedRoom',
        room: roomName,
        user: client.nickname
    });

    console.log(`${client.nickname} joined room: ${roomName}`);
}

// Handle client leaving a room
function leaveRoom(clientId) {
    const client = clients.get(clientId);
    if (!client || !client.currentRoom) return;

    const roomName = client.currentRoom;
    const room = rooms.get(roomName);

    if (room) {
        room.delete(clientId);

        // Broadcast leave message
        const leaveMessage = createMessage('system', roomName, 'System', `${client.nickname} left the room`);
        addToHistory(roomName, leaveMessage);
        broadcastToRoom(roomName, leaveMessage);

        // Send updated user list
        broadcastToRoom(roomName, {
            type: 'userList',
            room: roomName,
            users: getRoomUsers(roomName)
        });

        // Clean up empty rooms (optional)
        if (room.size === 0) {
            rooms.delete(roomName);
            // Keep message history for when users rejoin
        }
    }

    client.currentRoom = null;
    console.log(`${client.nickname} left room: ${roomName}`);
}

// Handle incoming messages
function handleMessage(clientId, data) {
    const client = clients.get(clientId);
    if (!client) return;

    let parsed;
    try {
        parsed = JSON.parse(data);
    } catch (e) {
        sendToClient(clientId, {
            type: 'error',
            content: 'Invalid JSON format'
        });
        return;
    }

    switch (parsed.type) {
        case 'setNickname':
            const oldNickname = client.nickname;
            client.nickname = parsed.nickname || `User_${clientId.substr(-4)}`;

            // Broadcast nickname change if in a room
            if (client.currentRoom) {
                const nicknameMessage = createMessage(
                    'system',
                    client.currentRoom,
                    'System',
                    `${oldNickname} is now known as ${client.nickname}`
                );
                addToHistory(client.currentRoom, nicknameMessage);
                broadcastToRoom(client.currentRoom, nicknameMessage);

                // Update user list
                broadcastToRoom(client.currentRoom, {
                    type: 'userList',
                    room: client.currentRoom,
                    users: getRoomUsers(client.currentRoom)
                });
            }

            sendToClient(clientId, {
                type: 'nicknameSet',
                nickname: client.nickname
            });
            console.log(`Nickname set: ${oldNickname} -> ${client.nickname}`);
            break;

        case 'join':
            if (!parsed.room) {
                sendToClient(clientId, {
                    type: 'error',
                    content: 'Room name required'
                });
                return;
            }
            joinRoom(clientId, parsed.room);
            break;

        case 'leave':
            leaveRoom(clientId);
            sendToClient(clientId, {
                type: 'leftRoom'
            });
            break;

        case 'message':
            if (!client.currentRoom) {
                sendToClient(clientId, {
                    type: 'error',
                    content: 'You must join a room first'
                });
                return;
            }

            const chatMessage = createMessage(
                'message',
                client.currentRoom,
                client.nickname,
                parsed.content
            );
            addToHistory(client.currentRoom, chatMessage);
            broadcastToRoom(client.currentRoom, chatMessage);
            break;

        case 'typing':
            if (!client.currentRoom) return;

            // Clear existing typing timeout
            if (client.typingTimeout) {
                clearTimeout(client.typingTimeout);
            }

            // Broadcast typing indicator
            broadcastToRoom(client.currentRoom, {
                type: 'typing',
                room: client.currentRoom,
                user: client.nickname,
                isTyping: true
            }, clientId);

            // Auto-clear typing after 3 seconds
            client.typingTimeout = setTimeout(() => {
                if (client.currentRoom) {
                    broadcastToRoom(client.currentRoom, {
                        type: 'typing',
                        room: client.currentRoom,
                        user: client.nickname,
                        isTyping: false
                    }, clientId);
                }
            }, 3000);
            break;

        case 'stopTyping':
            if (!client.currentRoom) return;

            if (client.typingTimeout) {
                clearTimeout(client.typingTimeout);
            }

            broadcastToRoom(client.currentRoom, {
                type: 'typing',
                room: client.currentRoom,
                user: client.nickname,
                isTyping: false
            }, clientId);
            break;

        case 'getRooms':
            const roomList = Array.from(rooms.keys()).map(name => ({
                name,
                userCount: rooms.get(name).size
            }));
            sendToClient(clientId, {
                type: 'roomList',
                rooms: roomList
            });
            break;

        default:
            sendToClient(clientId, {
                type: 'error',
                content: `Unknown message type: ${parsed.type}`
            });
    }
}

// WebSocket connection handler
wss.on('connection', (ws, req) => {
    const clientId = generateClientId();
    const defaultNickname = `User_${clientId.substr(-4)}`;

    // Store client
    clients.set(clientId, {
        ws,
        nickname: defaultNickname,
        currentRoom: null,
        typingTimeout: null
    });

    console.log(`Client connected: ${clientId}`);

    // Send welcome message
    sendToClient(clientId, {
        type: 'welcome',
        clientId,
        nickname: defaultNickname,
        message: 'Connected to chat server. Set your nickname and join a room!'
    });

    // Handle messages
    ws.on('message', (data) => {
        handleMessage(clientId, data.toString());
    });

    // Handle disconnect
    ws.on('close', () => {
        const client = clients.get(clientId);
        if (client) {
            if (client.typingTimeout) {
                clearTimeout(client.typingTimeout);
            }
            leaveRoom(clientId);
        }
        clients.delete(clientId);
        console.log(`Client disconnected: ${clientId}`);
    });

    // Handle errors
    ws.on('error', (error) => {
        console.error(`WebSocket error for ${clientId}:`, error.message);
    });
});

// Start server
const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
    console.log(`Chat server running on http://localhost:${PORT}`);
    console.log(`WebSocket server ready on ws://localhost:${PORT}`);
});

// Graceful shutdown
process.on('SIGINT', () => {
    console.log('\nShutting down server...');

    // Notify all clients
    clients.forEach((client, clientId) => {
        if (client.ws.readyState === WebSocket.OPEN) {
            client.ws.send(JSON.stringify({
                type: 'system',
                content: 'Server is shutting down'
            }));
            client.ws.close();
        }
    });

    wss.close(() => {
        server.close(() => {
            console.log('Server shut down complete');
            process.exit(0);
        });
    });
});
