  if (!messageHistory.has(roomName)) {
    messageHistory.set(roomName, []);
  }
  const history = messageHistory.get(roomName);
  history.push(message);
  if (history.length > MAX_HISTORY) {
    history.shift();
  }
}

function createMessage(type, room, user, content) {
  return {
    type,
    room,
    user,
    content,
    timestamp: new Date().toISOString(),
  };
}

function broadcastToRoom(roomName, message, excludeWs = null) {
  const room = rooms.get(roomName);
  if (!room) return;

  const payload = JSON.stringify(message);
  for (const memberWs of room) {
    if (memberWs !== excludeWs && memberWs.readyState === WebSocket.OPEN) {
      memberWs.send(payload);
    }
  }
}

function sendToClient(ws, message) {
  if (ws.readyState === WebSocket.OPEN) {
    ws.send(JSON.stringify(message));
  }
}

function getRoomUserList(roomName) {
  const room = rooms.get(roomName);
  if (!room) return [];
  const users = [];
  for (const memberWs of room) {
    const clientData = clients.get(memberWs);
    if (clientData) {
      users.push(clientData.nickname);
    }
  }
  return users;
}

function broadcastUserList(roomName) {
  const users = getRoomUserList(roomName);
  const message = {
    type: 'user_list',
    room: roomName,
    users,
    timestamp: new Date().toISOString(),
  };
  broadcastToRoom(roomName, message);
}

function handleJoinRoom(ws, clientData, roomName) {
  // Already in this room?
  if (clientData.rooms.has(roomName)) {
    sendToClient(ws, createMessage('error', roomName, 'system', 'You are already in this room.'));
    return;
  }

  const room = getOrCreateRoom(roomName);
  room.add(ws);
  clientData.rooms.add(roomName);

  // Send message history to the joining client
  const history = messageHistory.get(roomName) || [];
  sendToClient(ws, {
    type: 'history',
    room: roomName,
    messages: history,
    timestamp: new Date().toISOString(),
  });

  // System message: user joined
  const joinMsg = createMessage('system', roomName, 'system', `${clientData.nickname} joined the room.`);
  addMessageToHistory(roomName, joinMsg);
  broadcastToRoom(roomName, joinMsg);

  // Send updated user list
  broadcastUserList(roomName);

  // Confirm join to the client
  sendToClient(ws, createMessage('joined', roomName, clientData.nickname, `You joined ${roomName}.`));
}

function handleLeaveRoom(ws, clientData, roomName) {
  if (!clientData.rooms.has(roomName)) {
    sendToClient(ws, createMessage('error', roomName, 'system', 'You are not in this room.'));
    return;
  }

  const room = rooms.get(roomName);
  if (room) {
    room.delete(ws);
  }
  clientData.rooms.delete(roomName);

  // Clear any typing timer for this room
  if (clientData.typingTimers.has(roomName)) {
    clearTimeout(clientData.typingTimers.get(roomName));
    clientData.typingTimers.delete(roomName);
    // Broadcast typing stop
    broadcastToRoom(roomName, createMessage('typing_stop', roomName, clientData.nickname, ''));
  }

  // System message: user left
  const leaveMsg = createMessage('system', roomName, 'system', `${clientData.nickname} left the room.`);
  addMessageToHistory(roomName, leaveMsg);
  broadcastToRoom(roomName, leaveMsg);

  // Send updated user list
  broadcastUserList(roomName);

  // Confirm leave to the client
  sendToClient(ws, createMessage('left', roomName, clientData.nickname, `You left ${roomName}.`));

  // Clean up empty rooms
  if (room && room.size === 0) {
    rooms.delete(roomName);
    // Keep history even if room is empty (optional: uncomment next line to clear)
    // messageHistory.delete(roomName);
  }
}

function handleDisconnect(ws) {
  const clientData = clients.get(ws);
  if (!clientData) return;

  // Leave all rooms
  for (const roomName of clientData.rooms) {
    const room = rooms.get(roomName);
    if (room) {
      room.delete(ws);
    }

    // Clear typing timers
    if (clientData.typingTimers.has(roomName)) {
      clearTimeout(clientData.typingTimers.get(roomName));
      broadcastToRoom(roomName, createMessage('typing_stop', roomName, clientData.nickname, ''));
    }

    // System message
    const leaveMsg = createMessage('system', roomName, 'system', `${clientData.nickname} disconnected.`);
    addMessageToHistory(roomName, leaveMsg);
    broadcastToRoom(roomName, leaveMsg);

    broadcastUserList(roomName);

    // Clean up empty rooms
    if (room && room.size === 0) {
      rooms.delete(roomName);
    }
  }

  clients.delete(ws);
  console.log(`Client disconnected: ${clientData.nickname}`);
}

// --- WebSocket connection handler ---
wss.on('connection', (ws) => {
  console.log('New WebSocket connection');

  // Client starts without a nickname; must send set_nick first
  const clientData = {
    nickname: null,
    rooms: new Set(),
    typingTimers: new Map(),
  };
  clients.set(ws, clientData);

  // Prompt client to set nickname
  sendToClient(ws, createMessage('system', null, 'system', 'Welcome! Please set your nickname using the nickname field.'));

  ws.on('message', (raw) => {
    let msg;
    try {
      msg = JSON.parse(raw.toString());
    } catch (e) {
      sendToClient(ws, createMessage('error', null, 'system', 'Invalid JSON message.'));
      return;
    }

    const { type } = msg;

    switch (type) {
      // --- Set nickname ---
      case 'set_nick': {
        const nick = (msg.nickname || msg.content || '').trim();
        if (!nick || nick.length < 1 || nick.length > 30) {
          sendToClient(ws, createMessage('error', null, 'system', 'Nickname must be 1-30 characters.'));
          return;
        }

        // Check for duplicate nicknames
        for (const [otherWs, otherData] of clients) {
          if (otherWs !== ws && otherData.nickname === nick) {
            sendToClient(ws, createMessage('error', null, 'system', `Nickname "${nick}" is already taken.`));
            return;
          }
        }

        const oldNick = clientData.nickname;
        clientData.nickname = nick;

        if (oldNick) {
          // Notify rooms of name change
          for (const roomName of clientData.rooms) {
            const sysMsg = createMessage('system', roomName, 'system', `${oldNick} is now known as ${nick}.`);
            addMessageToHistory(roomName, sysMsg);
            broadcastToRoom(roomName, sysMsg);
            broadcastUserList(roomName);
          }
        }

        sendToClient(ws, createMessage('nick_set', null, nick, `Nickname set to ${nick}.`));
        console.log(`Nickname set: ${oldNick || '(new)'} -> ${nick}`);
        break;
      }

      // --- Join room ---
      case 'join': {
        if (!clientData.nickname) {
          sendToClient(ws, createMessage('error', null, 'system', 'Set a nickname before joining a room.'));
          return;
        }
        const roomName = (msg.room || '').trim();
        if (!roomName || roomName.length > 50) {
          sendToClient(ws, createMessage('error', null, 'system', 'Invalid room name.'));
          return;
        }
        handleJoinRoom(ws, clientData, roomName);
        break;
      }

      // --- Leave room ---
      case 'leave': {
        if (!clientData.nickname) return;
        const roomName = (msg.room || '').trim();
        if (!roomName) return;
        handleLeaveRoom(ws, clientData, roomName);
        break;
      }

      // --- Chat message ---
      case 'message': {
        if (!clientData.nickname) {
          sendToClient(ws, createMessage('error', null, 'system', 'Set a nickname first.'));
          return;
        }
        const roomName = (msg.room || '').trim();
        const content = (msg.content || '').trim();
        if (!roomName || !content) {
          sendToClient(ws, createMessage('error', null, 'system', 'Message must have room and content.'));
          return;
        }
        if (!clientData.rooms.has(roomName)) {
          sendToClient(ws, createMessage('error', roomName, 'system', 'You are not in this room.'));
          return;
        }
        if (content.length > 2000) {
          sendToClient(ws, createMessage('error', roomName, 'system', 'Message too long (max 2000 chars).'));
          return;
        }

        const chatMsg = createMessage('message', roomName, clientData.nickname, content);
        addMessageToHistory(roomName, chatMsg);
        broadcastToRoom(roomName, chatMsg); // broadcast to everyone including sender

        // Clear typing indicator since they sent a message
        if (clientData.typingTimers.has(roomName)) {
          clearTimeout(clientData.typingTimers.get(roomName));
          clientData.typingTimers.delete(roomName);
          broadcastToRoom(roomName, createMessage('typing_stop', roomName, clientData.nickname, ''), ws);
        }
        break;
      }

      // --- Typing indicator ---
      case 'typing': {
        if (!clientData.nickname) return;
        const roomName = (msg.room || '').trim();
        if (!roomName || !clientData.rooms.has(roomName)) return;

        // Broadcast typing_start, then auto-clear after 3 seconds
        if (!clientData.typingTimers.has(roomName)) {
          // First typing event — broadcast start
          broadcastToRoom(roomName, createMessage('typing_start', roomName, clientData.nickname, ''), ws);
        } else {
          // Reset the existing timer
          clearTimeout(clientData.typingTimers.get(roomName));
        }

        const timer = setTimeout(() => {
          clientData.typingTimers.delete(roomName);
          broadcastToRoom(roomName, createMessage('typing_stop', roomName, clientData.nickname, ''), ws);
        }, 3000);

        clientData.typingTimers.set(roomName, timer);
        break;
      }

      // --- List rooms ---
      case 'list_rooms': {
        const roomList = [];
        for (const [name, members] of rooms) {
          roomList.push({ name, members: members.size });
        }
        sendToClient(ws, {
          type: 'room_list',
          rooms: roomList,
          timestamp: new Date().toISOString(),
        });
        break;
      }

      default:
        sendToClient(ws, createMessage('error', null, 'system', `Unknown message type: ${type}`));
    }
  });

  ws.on('close', () => handleDisconnect(ws));
  ws.on('error', (err) => {
    console.error('WebSocket error:', err.message);
    handleDisconnect(ws);
  });
});

console.log('Chat server initialized.');
