<script>
(function() {
  // --- State ---
  let ws = null;
  let myNickname = null;
  let activeRoom = null;
  // roomName -> { messages: [], users: [], typingUsers: Set, unread: number }
  const roomData = {};

  // --- DOM refs ---
  const statusDot     = document.getElementById('connection-status');
  const nickInput     = document.getElementById('nick-input');
  const nickBtn       = document.getElementById('nick-btn');
  const roomInput     = document.getElementById('room-input');
  const joinBtn       = document.getElementById('join-btn');
  const roomListEl    = document.getElementById('room-list');
  const chatHeader    = document.getElementById('chat-room-header');
  const noRoomEl      = document.getElementById('no-room-selected');
  const messagesEl    = document.getElementById('messages');
  const typingEl      = document.getElementById('typing-indicator');
  const msgInput      = document.getElementById('msg-input');
  const sendBtn       = document.getElementById('send-btn');
  const userListEl    = document.getElementById('user-list');

  // --- WebSocket connection ---
  function connect() {
    const protocol = location.protocol === 'https:' ? 'wss:' : 'ws:';
    ws = new WebSocket(`${protocol}//${location.host}`);

    ws.onopen = () => {
      statusDot.classList.add('connected');
      statusDot.title = 'Connected';
      console.log('Connected to server');
    };

    ws.onclose = () => {
      statusDot.classList.remove('connected');
      statusDot.title = 'Disconnected';
      console.log('Disconnected. Reconnecting in 3s...');
      setTimeout(connect, 3000);
    };

    ws.onerror = (err) => {
      console.error('WebSocket error', err);
    };

    ws.onmessage = (event) => {
      let msg;
      try { msg = JSON.parse(event.data); } catch(e) { return; }
      handleServerMessage(msg);
    };
  }

  function send(obj) {
    if (ws && ws.readyState === WebSocket.OPEN) {
      ws.send(JSON.stringify(obj));
    }
  }

  // --- Handle incoming messages ---
  function handleServerMessage(msg) {
    switch (msg.type) {
      case 'nick_set':
        myNickname = msg.user;
        nickInput.value = myNickname;
        nickInput.disabled = false;
        break;

      case 'joined':
        ensureRoomData(msg.room);
        renderRoomList();
        switchToRoom(msg.room);
        break;

      case 'left':
        if (roomData[msg.room]) {
          delete roomData[msg.room];
        }
        if (activeRoom === msg.room) {
          activeRoom = null;
          const remaining = Object.keys(roomData);
          if (remaining.length > 0) {
            switchToRoom(remaining[0]);
          } else {
            renderChatArea();
          }
        }
        renderRoomList();
        break;

      case 'history':
        ensureRoomData(msg.room);
        roomData[msg.room].messages = msg.messages || [];
        if (activeRoom === msg.room) renderMessages();
        break;

      case 'message':
        ensureRoomData(msg.room);
        roomData[msg.room].messages.push(msg);
        if (activeRoom === msg.room) {
          renderMessages();
        } else {
          roomData[msg.room].unread++;
          renderRoomList();
        }
        break;

