### Server Code (`server.js`)

This server uses only the `ws` package. It manages rooms, nicknames, message history, and broadcasts messages including system and typing notifications.

```javascript
// server.js
const { WebSocketServer, WebSocket } = require('ws');

const PORT = process.env.PORT || 8080;

// Initialize a new WebSocket server instance
const wss = new WebSocketServer({ port: PORT });

// In-memory data structures
const rooms = new Map(); // Map<roomName, Set<WebSocket>>
const messageHistory = new Map(); // Map<roomName, Array<Object>>
const MAX_HISTORY = 50;

console.log(`WebSocket chat server started on ws://localhost:${PORT}`);

// --- Helper Functions ---

/**
 * Broadcasts a message to all clients in a specific room.
 * @param {string} roomName - The name of the room.
 * @param {string} message - The message to send (as a JSON string).
 * @param {WebSocket} [excludeClient] - A client to exclude from the broadcast.
 */
function broadcast(roomName, message, excludeClient) {
    const room = rooms.get(roomName);
    if (!room) return;

    room.forEach(client => {
        if (client !== excludeClient && client.readyState === WebSocket.OPEN) {
            client.send(message);
        }
    });
}

/**
 * Stores a message in the history for a given room.
 * @param {string} roomName - The name of the room.
 * @param {object} message - The message object to store.
 */
function storeMessage(roomName, message) {
    if (!messageHistory.has(roomName)) {
        messageHistory.set(roomName, []);
    }
    const history = messageHistory.get(roomName);
    history.push(message);
    // Keep history capped at MAX_HISTORY
    if (history.length > MAX_HISTORY) {
        history.shift();
    }
}

/**
 * Handles a user leaving a room, including cleanup and notification.
 * @param {WebSocket} ws - The WebSocket connection of the user.
 */
function handleLeaveRoom(ws) {
    if (!ws.currentRoom || !ws.nickname) return;

    const roomName = ws.currentRoom;
    const room = rooms.get(roomName);

    if (room) {
        room.delete(ws); // Remove user from room set

        // Broadcast leave message
        const leaveMessage = {
            type: 'system',
            content: `${ws.nickname} has left the room.`,
            timestamp: new Date().toISOString()
        };
        broadcast(roomName, JSON.stringify(leaveMessage));

        // If room is empty, clean it up
        if (room.size === 0) {
            rooms.delete(roomName);
            messageHistory.delete(roomName);
            console.log(`Room '${roomName}' is now empty and has been closed.`);
        }
    }
    ws.currentRoom = null;
}


// --- WebSocket Server Logic ---

wss.on('connection', (ws) => {
    console.log('Client connected.');

    // Attach metadata to the WebSocket object
    ws.nickname = null;
    ws.currentRoom = null;

    ws.on('message', (rawMessage) => {
        let data;
        try {
            data = JSON.parse(rawMessage);
        } catch (e) {
            console.error('Invalid JSON received:', rawMessage);
            return;
        }

        // The first message must be to set the nickname
        if (!ws.nickname && data.type !== 'setNickname') {
            ws.send(JSON.stringify({ type: 'error', content: 'Please set a nickname first.' }));
            return;
        }

        switch (data.type) {
            case 'setNickname':
                ws.nickname = data.content;
                console.log(`User set nickname to: ${ws.nickname}`);
                break;

            case 'joinRoom':
                // Leave previous room if they were in one
                handleLeaveRoom(ws);

                const roomName = data.room;
                ws.currentRoom = roomName;

                // Create room if it doesn't exist
                if (!rooms.has(roomName)) {
                    rooms.set(roomName, new Set());
                    console.log(`Room '${roomName}' created.`);
                }

                // Add user to the new room
                rooms.get(roomName).add(ws);
                console.log(`User '${ws.nickname}' joined room '${roomName}'`);

                // Send message history to the joining user
                const history = messageHistory.get(roomName) || [];
                ws.send(JSON.stringify({ type: 'history', content: history }));

                // Broadcast join message to the room
                const joinMessage = {
                    type: 'system',
                    content: `${ws.nickname} has joined the room.`,
                    timestamp: new Date().toISOString()
                };
                broadcast(roomName, JSON.stringify(joinMessage), ws); // Exclude sender
                break;

            case 'chatMessage':
                if (!ws.currentRoom) return;

                const chatMessage = {
                    type: 'chatMessage',
                    user: ws.nickname,
                    room: ws.currentRoom,
                    content: data.content,
                    timestamp: new Date().toISOString()
                };
                storeMessage(ws.currentRoom, chatMessage);
                broadcast(ws.currentRoom, JSON.stringify(chatMessage));
                break;

            case 'typing':
                if (!ws.currentRoom) return;

                const typingMessage = {
                    type: 'typing',
                    user: ws.nickname,
                    room: ws.currentRoom
                };
                // Broadcast to everyone else in the room
                broadcast(ws.currentRoom, JSON.stringify(typingMessage), ws);
                break;
        }
    });

    ws.on('close', () => {
        console.log(`Client '${ws.nickname || 'unknown'}' disconnected.`);
        // Handle leaving the room on disconnect
        handleLeaveRoom(ws);
    });

    ws.on('error', (error) => {
        console.error('WebSocket error:', error);
    });
});
