#!/usr/bin/env python3
"""
fstats - File Statistics CLI Tool

A command-line tool to analyze directory statistics and compare directories.
No external dependencies required (uses Python standard library).
"""

import argparse
import csv
import fnmatch
import hashlib
import json
import os
import sys
import time
from datetime import datetime
from io import StringIO
from pathlib import Path
from typing import Any, Dict, List, Optional, Tuple

# --- Constants & Color Codes ---

COLORS = {
    'reset': '\033[0m',
    'bold': '\033[1m',
    'red': '\033[91m',
    'green': '\033[92m',
    'yellow': '\033[93m',
    'blue': '\033[94m',
    'cyan': '\033[96m',
}

def supports_color() -> bool:
    """Check if the terminal supports color."""
    if os.environ.get('NO_COLOR'):
        return False
    if not sys.stdout.isatty():
        return False
    # Windows 10+ supports ANSI, older versions might need colorama, 
    # but we stick to standard ANSI for simplicity/cross-platform compatibility in modern envs
    return True

USE_COLOR = supports_color()

def c(text: str, color: str) -> str:
    """Wrap text in color codes if supported."""
    if USE_COLOR and color in COLORS:
        return f"{COLORS[color]}{text}{COLORS['reset']}"
    return text

# --- Helper Functions ---

def format_size(size_bytes: int) -> str:
    """Convert bytes to human-readable string."""
    if size_bytes == 0:
        return "0 B"
    units = ['B', 'KB', 'MB', 'GB', 'TB']
    i = 0
    size = float(size_bytes)
    while size >= 1024 and i < len(units) - 1:
        size /= 1024
        i += 1
    return f"{size:.2f} {units[i]}"

def get_file_hash(filepath: Path, chunk_size: int = 8192) -> Optional[str]:
    """Calculate SHA-256 hash of a file."""
    try:
        sha256 = hashlib.sha256()
        with filepath.open('rb') as f:
            for chunk in iter(lambda: f.read(chunk_size), b''):
                sha256.update(chunk)
        return sha256.hexdigest()
    except (PermissionError, OSError):
        return None

def get_extension(filepath: Path) -> str:
    """Get file extension, handling hidden files and no-extension cases."""
    ext = filepath.suffix.lower()
    return ext if ext else "(no extension)"

def should_exclude(path: Path, patterns: List[str]) -> bool:
    """Check if path matches any exclude glob pattern."""
    if not patterns:
        return False
    # Check against the full relative path and the name
    name = path.name
    path_str = str(path)
    for pattern in patterns:
        if fnmatch.fnmatch(name, pattern) or fnmatch.fnmatch(path_str, pattern):
            return True
    return False

def simple_table(headers: List[str], rows: List[List[str]]) -> str:
    """Generate a simple ASCII table."""
    if not rows:
        return "No data."

    # Calculate column widths
    widths = [len(h) for h in headers]
    for row in rows:
        for i, cell in enumerate(row):
            if i < len(widths):
                widths[i] = max(widths[i], len(str(cell)))

    # Build table
    lines = []
    separator = "+" + "+".join("-" * (w + 2) for w in widths) + "+"

    # Header
    header_line = "|" + "|".join(f" {h:<{widths[i]}} " for i, h in enumerate(headers)) + "|"
    lines.append(separator)
    lines.append(header_line)
    lines.append(separator)

    # Rows
    for row in rows:
        # Pad row if missing columns
        while len(row) < len(headers):
            row.append("")
        row_line = "|" + "|".join(f" {str(cell):<{widths[i]}} " for i, cell in enumerate(row)) + "|"
        lines.append(row_line)

    lines.append(separator)
    return "\n".join(lines)

# --- Core Logic ---

class FileScanner:
    def __init__(self, root_path: Path, exclude_patterns: List[str], show_progress: bool = True):
        self.root = root_path.resolve()
        self.exclude = exclude_patterns
        self.show_progress = show_progress
        self.files: List[Dict[str, Any]] = []
        self.count = 0

    def scan(self) -> List[Dict[str, Any]]:
        """Recursively scan directory and collect file metadata."""
        self.files = []
        self.count = 0
        start_time = time.time()

        # We cannot know total count easily without walking twice. 
        # We will just report progress based on count.

        try:
            for path in self.root.rglob('*'):
                if path.is_file():
                    if should_exclude(path.relative_to(self.root), self.exclude):
                        continue

                    try:
                        stat = path.stat()
                        self.files.append({
                            'path': str(path.relative_to(self.root)),
                            'size': stat.st_size,
                            'mtime': stat.st_mtime,
                            'ext': get_extension(path),
                            'hash': None # Calculated later if needed
                        })
                        self.count += 1

                        if self.show_progress and self.count % 100 == 0:
                            sys.stderr.write(f"\rScanning... {self.count} files found")
                            sys.stderr.flush()
                    except (PermissionError, OSError):
                        continue
        except KeyboardInterrupt:
            sys.stderr.write("\nScan interrupted.\n")

        if self.show_progress:
            sys.stderr.write(f"\rScanning complete. {self.count} files in {time.time() - start_time:.2f}s\n")
            sys.stderr.flush()

        return self.files

def analyze_directory(path: str, exclude: List[str], fmt: str) -> Dict[str, Any]:
    """Perform analysis on a directory."""
    root = Path(path)
    if not root.exists():
        raise FileNotFoundError(f"Path does not exist: {path}")
    if not root.is_dir():
        raise NotADirectoryError(f"Path is not a directory: {path}")

    scanner = FileScanner(root, exclude)
    files = scanner.scan()

    if not files:
        return {"error": "No files found"}

    # 1. Count & Size by Extension
    ext_stats: Dict[str, Dict[str, int]] = {}
    for f in files:
        ext = f['ext']
        if ext not in ext_stats:
            ext_stats[ext] = {'count': 0, 'size': 0}
        ext_stats[ext]['count'] += 1
        ext_stats[ext]['size'] += f['size']

    # 2. Largest 10 Files
    largest = sorted(files, key=lambda x: x['size'], reverse=True)[:10]

    # 3. Duplicates (Optimization: Group by size first)
    size_groups: Dict[int, List[Dict]] = {}
    for f in files:
        if f['size'] not in size_groups:
            size_groups[f['size']] = []
        size_groups[f['size']].append(f)

    duplicates = []
    # Only hash files that have same size as another file
    files_to_hash = [f for group in size_groups.values() if len(group) > 1 for f in group]

    # Hashing progress
    if files_to_hash:
        sys.stderr.write(f"Checking duplicates (hashing {len(files_to_hash)} files)...\n")
        sys.stderr.flush()

    hash_groups: Dict[str, List[Dict]] = {}
    for f in files_to_hash:
        full_path = root / f['path']
        h = get_file_hash(full_path)
        if h:
            f['hash'] = h
            if h not in hash_groups:
                hash_groups[h] = []
            hash_groups[h].append(f)

    for h, group in hash_groups.items():
        if len(group) > 1:
            duplicates.append({
                'hash': h,
                'size': group[0]['size'],
                'files': [f['path'] for f in group]
            })

    # 4. Average File Age
    now = time.time()
    ages = [(now - f['mtime']) for f in files]
    avg_age_seconds = sum(ages) / len(ages) if ages else 0

    # Construct Result
    result = {
        "summary": {
            "total_files": len(files),
            "total_size": sum(f['size'] for f in files),
            "avg_age_days": round(avg_age_seconds / 86400, 2)
        },
        "by_extension": [
            {"extension": k, "count": v['count'], "size": v['size']} 
            for k, v in sorted(ext_stats.items(), key=lambda x: x[1]['size'], reverse=True)
        ],
        "largest_files": [
            {"path": f['path'], "size": f['size']} for f in largest
        ],
        "duplicates": duplicates
    }
    return result

def compare_directories(path1: str, path2: str, exclude: List[str], fmt: str) -> Dict[str, Any]:
    """Compare two directories."""
    root1 = Path(path1).resolve()
    root2 = Path(path2).resolve()

    if not root1.is_dir() or not root2.is_dir():
        raise NotADirectoryError("Both paths must be directories")

    # Scan both
    scanner1 = FileScanner(root1, exclude, show_progress=False)
    scanner2 = FileScanner(root2, exclude, show_progress=False)

    # We need hashes for comparison of content
    sys.stderr.write(f"Scanning {path1}...\n")
    files1 = scanner1.scan()
    sys.stderr.write(f"Scanning {path2}...\n")
    files2 = scanner2.scan()

    # Map relative path -> file info
    map1: Dict[str, Dict] = {f['path']: f for f in files1}
    map2: Dict[str, Dict] = {f['path']: f for f in files2}

    paths1 = set(map1.keys())
    paths2 = set(map2.keys())

    only_in_1 = sorted(list(paths1 - paths2))
    only_in_2 = sorted(list(paths2 - paths1))
    common = paths1 & paths2

    modified = []
    identical_count = 0

    sys.stderr.write("Comparing common files (hashing)...\n")
    for p in common:
        f1 = map1[p]
        f2 = map2[p]

        # Quick check: size
        if f1['size'] != f2['size']:
            modified.append({"path": p, "reason": "size_mismatch", "size1": f1['size'], "size2": f2['size']})
            continue

        # Deep check: hash
        h1 = get_file_hash(root1 / p)
        h2 = get_file_hash(root2 / p)

        if h1 and h2:
            if h1 != h2:
                modified.append({"path": p, "reason": "content_mismatch", "hash1": h1[:8], "hash2": h2[:8]})
            else:
                identical_count += 1
        else:
            modified.append({"path": p, "reason": "hash_error"})

    result = {
        "summary": {
            "path1": str(root1),
            "path2": str(root2),
            "only_in_path1": len(only_in_1),
            "only_in_path2": len(only_in_2),
            "modified": len(modified),
            "identical": identical_count
        },
        "only_in_path1": only_in_1,
        "only_in_path2": only_in_2,
        "modified": modified
    }
    return result

# --- Output Formatters ---

def output_result(result: Dict[str, Any], fmt: str, command: str):
    """Format and print the result based on requested format."""

    if fmt == 'json':
        print(json.dumps(result, indent=2))
        return

    if fmt == 'csv':
        # CSV is tricky for nested structures. We flatten based on command.
        writer = csv.writer(sys.stdout)
        if command == 'analyze':
            writer.writerow(['section', 'key', 'value'])
            writer.writerow(['summary', 'total_files', result['summary']['total_files']])
            writer.writerow(['summary', 'total_size', result['summary']['total_size']])
            writer.writerow(['summary', 'avg_age_days', result['summary']['avg_age_days']])

            for item in result['by_extension']:
                writer.writerow(['extension', item['extension'], f"{item['count']} files, {format_size(item['size'])}"])

            for item in result['largest_files']:
                writer.writerow(['largest', item['path'], format_size(item['size'])])

            for dup in result['duplicates']:
                writer.writerow(['duplicate', dup['hash'], "; ".join(dup['files'])])

        elif command == 'compare':
            writer.writerow(['category', 'path', 'details'])
            for p in result['only_in_path1']:
                writer.writerow(['only_in_path1', p, ''])
            for p in result['only_in_path2']:
                writer.writerow(['only_in_path2', p, ''])
            for m in result['modified']:
                writer.writerow(['modified', m['path'], m['reason']])
        return

    if fmt == 'table':
        # Custom Table Rendering
        if command == 'analyze':
            print(c("\n=== Summary ===", 'bold'))
            print(f"Total Files: {result['summary']['total_files']}")
            print(f"Total Size: {format_size(result['summary']['total_size'])}")
            print(f"Average Age: {result['summary']['avg_age_days']} days")

            print(c("\n=== Size by Extension ===", 'bold'))
            headers = ['Extension', 'Count', 'Total Size']
            rows = [[e['extension'], e['count'], format_size(e['size'])] for e in result['by_extension']]
            print(simple_table(headers, rows))

            print(c("\n=== Largest 10 Files ===", 'bold'))
            headers = ['Path', 'Size']
            rows = [[f['path'], format_size(f['size'])] for f in result['largest_files']]
            print(simple_table(headers, rows))

            print(c("\n=== Duplicates ===", 'bold'))
            if result['duplicates']:
                for dup in result['duplicates']:
                    print(f"{c('Hash:', 'cyan')} {dup['hash'][:16]}... ({format_size(dup['size'])})")
                    for f in dup['files']:
                        print(f"  - {f}")
            else:
                print("No duplicates found.")

        elif command == 'compare':
            print(c("\n=== Comparison Summary ===", 'bold'))
            print(f"Path 1: {result['summary']['path1']}")
            print(f"Path 2: {result['summary']['path2']}")
            print(f"Only in Path 1: {c(str(result['summary']['only_in_path1']), 'yellow')}")
            print(f"Only in Path 2: {c(str(result['summary']['only_in_path2']), 'yellow')}")
            print(f"Modified: {c(str(result['summary']['modified']), 'red')}")
            print(f"Identical: {c(str(result['summary']['identical']), 'green')}")

            if result['only_in_path1']:
                print(c("\n--- Only in Path 1 ---", 'yellow'))
                for p in result['only_in_path1'][:20]: # Limit output
                    print(f"  {p}")
                if len(result['only_in_path1']) > 20:
                    print(f"  ... and {len(result['only_in_path1']) - 20} more")

            if result['only_in_path2']:
                print(c("\n--- Only in Path 2 ---", 'yellow'))
                for p in result['only_in_path2'][:20]:
                    print(f"  {p}")
                if len(result['only_in_path2']) > 20:
                    print(f"  ... and {len(result['only_in_path2']) - 20} more")

            if result['modified']:
                print(c("\n--- Modified Files ---", 'red'))
                for m in result['modified'][:20]:
                    print(f"  {m['path']} ({m['reason']})")
                if len(result['modified']) > 20:
                    print(f"  ... and {len(result['modified']) - 20} more")

# --- CLI Entry Point ---

def main():
    parser = argparse.ArgumentParser(
        prog='fstats',
        description='File Statistics and Directory Comparison Tool'
    )

    # Global Options
    parser.add_argument('--format', choices=['json', 'table', 'csv'], default='table',
                        help='Output format (default: table)')
    parser.add_argument('--exclude', action='append', default=[],
                        help='Glob pattern to exclude (can be used multiple times)')
    parser.add_argument('--no-color', action='store_true',
                        help='Disable color output')

    subparsers = parser.add_subparsers(dest='command', required=True, help='Available commands')

    # Analyze Command
    p_analyze = subparsers.add_parser('analyze', help='Analyze a directory')
    p_analyze.add_argument('path', type=str, help='Directory path to analyze')

    # Compare Command
    p_compare = subparsers.add_parser('compare', help='Compare two directories')
    p_compare.add_argument('path1', type=str, help='First directory path')
    p_compare.add_argument('path2', type=str, help='Second directory path')

    args = parser.parse_args()

    # Handle Color
    global USE_COLOR
    if args.no_color:
        USE_COLOR = False

    try:
        if args.command == 'analyze':
            result = analyze_directory(args.path, args.exclude, args.format)
            output_result(result, args.format, 'analyze')

        elif args.command == 'compare':
            result = compare_directories(args.path1, args.path2, args.exclude, args.format)
            output_result(result, args.format, 'compare')

    except FileNotFoundError as e:
        print(c(f"Error: {e}", 'red'), file=sys.stderr)
        sys.exit(1)
    except NotADirectoryError as e:
        print(c(f"Error: {e}", 'red'), file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(c(f"Unexpected Error: {e}", 'red'), file=sys.stderr)
        sys.exit(1)

if __name__ == '__main__':
    main()
