# `fstats` - File Statistics CLI Tool

A comprehensive Python CLI tool for analyzing and comparing directories.

```python
#!/usr/bin/env python3
"""
fstats - File Statistics CLI Tool

A command-line tool for analyzing directory contents and comparing directories.
"""

import argparse
import csv
import fnmatch
import hashlib
import io
import json
import os
import sys
from collections import defaultdict
from dataclasses import dataclass, field, asdict
from datetime import datetime
from pathlib import Path
from typing import Iterator


# ============================================================================
# Color Support
# ============================================================================

class Colors:
    """ANSI color codes for terminal output."""

    HEADER = '\033[95m'
    BLUE = '\033[94m'
    CYAN = '\033[96m'
    GREEN = '\033[92m'
    YELLOW = '\033[93m'
    RED = '\033[91m'
    BOLD = '\033[1m'
    UNDERLINE = '\033[4m'
    END = '\033[0m'

    _enabled = True

    @classmethod
    def disable(cls):
        """Disable color output."""
        cls._enabled = False

    @classmethod
    def is_enabled(cls) -> bool:
        """Check if colors are enabled."""
        return cls._enabled and sys.stdout.isatty()

    @classmethod
    def colorize(cls, text: str, color: str) -> str:
        """Apply color to text if colors are enabled."""
        if cls.is_enabled():
            return f"{color}{text}{cls.END}"
        return text

    @classmethod
    def header(cls, text: str) -> str:
        return cls.colorize(text, cls.HEADER + cls.BOLD)

    @classmethod
    def success(cls, text: str) -> str:
        return cls.colorize(text, cls.GREEN)

    @classmethod
    def warning(cls, text: str) -> str:
        return cls.colorize(text, cls.YELLOW)

    @classmethod
    def error(cls, text: str) -> str:
        return cls.colorize(text, cls.RED)

    @classmethod
    def info(cls, text: str) -> str:
        return cls.colorize(text, cls.CYAN)

    @classmethod
    def bold(cls, text: str) -> str:
        return cls.colorize(text, cls.BOLD)


# ============================================================================
# Progress Indicator
# ============================================================================

class ProgressIndicator:
    """Simple progress indicator for terminal output."""

    SPINNER_CHARS = ['⠋', '⠙', '⠹', '⠸', '⠼', '⠴', '⠦', '⠧', '⠇', '⠏']
    FALLBACK_CHARS = ['|', '/', '-', '\\']

    def __init__(self, message: str = "Processing"):
        self.message = message
        self.count = 0
        self.spinner_idx = 0
        self._enabled = sys.stderr.isatty()
        # Use fallback characters if terminal might not support Unicode
        self.chars = self.SPINNER_CHARS if self._supports_unicode() else self.FALLBACK_CHARS

    @staticmethod
    def _supports_unicode() -> bool:
        """Check if terminal likely supports Unicode."""
        try:
            return sys.stderr.encoding.lower().startswith('utf')
        except (AttributeError, TypeError):
            return False

    def update(self, current_file: str = ""):
        """Update the progress indicator."""
        if not self._enabled:
            return

        self.count += 1
        self.spinner_idx = (self.spinner_idx + 1) % len(self.chars)
        spinner = self.chars[self.spinner_idx]

        # Truncate filename if too long
        max_len = 50
        if len(current_file) > max_len:
            current_file = "..." + current_file[-(max_len - 3):]

        status = f"\r{spinner} {self.message}: {self.count} files processed"
        if current_file:
            status += f" | {current_file}"

        # Clear line and write status
        sys.stderr.write(f"\r{' ' * 100}\r")
        sys.stderr.write(status)
        sys.stderr.flush()

    def finish(self):
        """Clear the progress indicator."""
        if self._enabled:
            sys.stderr.write(f"\r{' ' * 100}\r")
            sys.stderr.flush()


# ============================================================================
# Data Classes
# ============================================================================

@dataclass
class FileInfo:
    """Information about a single file."""
    path: str
    name: str
    extension: str
    size: int
    modified_time: float
    hash: str = ""

    def to_dict(self) -> dict:
        return {
            'path': self.path,
            'name': self.name,
            'extension': self.extension,
            'size': self.size,
            'modified_time': self.modified_time,
            'modified_date': datetime.fromtimestamp(self.modified_time).isoformat(),
            'hash': self.hash
        }


@dataclass
class AnalysisResult:
    """Results from directory analysis."""
    root_path: str
    total_files: int = 0
    total_size: int = 0
    count_by_extension: dict = field(default_factory=dict)
    size_by_extension: dict = field(default_factory=dict)
    largest_files: list = field(default_factory=list)
    duplicates: dict = field(default_factory=dict)
    average_age_days: float = 0.0
    oldest_file: dict = field(default_factory=dict)
    newest_file: dict = field(default_factory=dict)

    def to_dict(self) -> dict:
        return {
            'root_path': self.root_path,
            'total_files': self.total_files,
            'total_size': self.total_size,
            'total_size_human': format_size(self.total_size),
            'count_by_extension': self.count_by_extension,
            'size_by_extension': {k: {'bytes': v, 'human': format_size(v)} 
                                  for k, v in self.size_by_extension.items()},
            'largest_files': self.largest_files,
            'duplicates': self.duplicates,
            'average_age_days': round(self.average_age_days, 2),
            'oldest_file': self.oldest_file,
            'newest_file': self.newest_file
        }


@dataclass
class CompareResult:
    """Results from directory comparison."""
    path1: str
    path2: str
    only_in_path1: list = field(default_factory=list)
    only_in_path2: list = field(default_factory=list)
    modified_files: list = field(default_factory=list)
    identical_files: list = field(default_factory=list)
    summary: dict = field(default_factory=dict)

    def to_dict(self) -> dict:
        return {
            'path1': self.path1,
            'path2': self.path2,
            'only_in_path1': self.only_in_path1,
            'only_in_path2': self.only_in_path2,
            'modified_files': self.modified_files,
            'identical_files_count': len(self.identical_files),
            'summary': self.summary
        }


# ============================================================================
# Utility Functions
# ============================================================================

def format_size(size_bytes: int) -> str:
    """Format bytes into human-readable size."""
    for unit in ['B', 'KB', 'MB', 'GB', 'TB']:
        if size_bytes < 1024:
            return f"{size_bytes:.2f} {unit}"
        size_bytes /= 1024
    return f"{size_bytes:.2f} PB"


def calculate_file_hash(filepath: str, chunk_size: int = 8192) -> str:
    """Calculate MD5 hash of a file."""
    hasher = hashlib.md5()
    try:
        with open(filepath, 'rb') as f:
            for chunk in iter(lambda: f.read(chunk_size), b''):
                hasher.update(chunk)
        return hasher.hexdigest()
    except (IOError, OSError):
        return ""


def get_extension(filename: str) -> str:
    """Get file extension, normalized to lowercase."""
    ext = Path(filename).suffix.lower()
    return ext if ext else "(no extension)"


def matches_exclude_pattern(path: str, patterns: list) -> bool:
    """Check if path matches any exclude pattern."""
    if not patterns:
        return False

    path_str = str(path)
    for pattern in patterns:
        if fnmatch.fnmatch(path_str, pattern):
            return True
        if fnmatch.fnmatch(os.path.basename(path_str), pattern):
            return True
    return False


def walk_directory(root_path: str, exclude_patterns: list = None, 
                   progress: ProgressIndicator = None) -> Iterator[FileInfo]:
    """Walk directory and yield FileInfo for each file."""
    exclude_patterns = exclude_patterns or []
    root = Path(root_path)

    if not root.exists():
        raise FileNotFoundError(f"Path does not exist: {root_path}")

    if not root.is_dir():
        raise NotADirectoryError(f"Path is not a directory: {root_path}")

    for dirpath, dirnames, filenames in os.walk(root):
        # Filter out excluded directories
        dirnames[:] = [d for d in dirnames 
                       if not matches_exclude_pattern(os.path.join(dirpath, d), exclude_patterns)]

        for filename in filenames:
            filepath = os.path.join(dirpath, filename)

            if matches_exclude_pattern(filepath, exclude_patterns):
                continue

            try:
                stat = os.stat(filepath)

                if progress:
                    progress.update(filepath)

                yield FileInfo(
                    path=filepath,
                    name=filename,
                    extension=get_extension(filename),
                    size=stat.st_size,
                    modified_time=stat.st_mtime
                )
            except (OSError, IOError):
                # Skip files we can't access
                continue


# ============================================================================
# Analysis Functions
# ============================================================================

def analyze_directory(path: str, exclude_patterns: list = None, 
                      show_progress: bool = True) -> AnalysisResult:
    """Analyze a directory and return statistics."""
    result = AnalysisResult(root_path=os.path.abspath(path))

    count_by_ext = defaultdict(int)
    size_by_ext = defaultdict(int)
    all_files = []
    hash_to_files = defaultdict(list)
    total_age = 0.0
    now = datetime.now().timestamp()

    oldest_time = float('inf')
    newest_time = 0
    oldest_file = None
    newest_file = None

    progress = ProgressIndicator("Analyzing") if show_progress else None

    try:
        for file_info in walk_directory(path, exclude_patterns, progress):
            result.total_files += 1
            result.total_size += file_info.size

            count_by_ext[file_info.extension] += 1
            size_by_ext[file_info.extension] += file_info.size

            all_files.append(file_info)

            # Track age
            age_days = (now - file_info.modified_time) / 86400
            total_age += age_days

            # Track oldest/newest
            if file_info.modified_time < oldest_time:
                oldest_time = file_info.modified_time
                oldest_file = file_info
            if file_info.modified_time > newest_time:
                newest_time = file_info.modified_time
                newest_file = file_info
    finally:
        if progress:
            progress.finish()

    # Sort and get largest files
    all_files.sort(key=lambda f: f.size, reverse=True)
    result.largest_files = [
        {
            'path': f.path,
            'size': f.size,
            'size_human': format_size(f.size)
        }
        for f in all_files[:10]
    ]

    # Calculate hashes for duplicate detection
    if show_progress:
        progress = ProgressIndicator("Calculating hashes")

    try:
        for file_info in all_files:
            if progress:
                progress.update(file_info.path)
            file_hash = calculate_file_hash(file_info.path)
            if file_hash:
                hash_to_files[file_hash].append(file_info.path)
    finally:
        if progress:
            progress.finish()

    # Find duplicates
    duplicates = {h: files for h, files in hash_to_files.items() if len(files) > 1}
    result.duplicates = {
        'groups': [
            {'hash': h, 'files': files, 'count': len(files)}
            for h, files in duplicates.items()
        ],
        'total_duplicate_groups': len(duplicates),
        'total_duplicate_files': sum(len(f) - 1 for f in duplicates.values())
    }

    # Convert defaultdicts to regular dicts
    result.count_by_extension = dict(sorted(count_by_ext.items(), 
                                            key=lambda x: x[1], reverse=True))
    result.size_by_extension = dict(sorted(size_by_ext.items(), 
                                           key=lambda x: x[1], reverse=True))

    # Calculate average age
    if result.total_files > 0:
        result.average_age_days = total_age / result.total_files

    # Set oldest/newest
    if oldest_file:
        result.oldest_file = {
            'path': oldest_file.path,
            'date': datetime.fromtimestamp(oldest_file.modified_time).isoformat()
        }
    if newest_file:
        result.newest_file = {
            'path': newest_file.path,
            'date': datetime.fromtimestamp(newest_file.modified_time).isoformat()
        }

    return result


def compare_directories(path1: str, path2: str, exclude_patterns: list = None,
                        show_progress: bool = True) -> CompareResult:
    """Compare two directories."""
    result = CompareResult(
        path1=os.path.abspath(path1),
        path2=os.path.abspath(path2)
    )

    # Build file maps (relative path -> FileInfo)
    def build_file_map(path: str, label: str) -> dict:
        file_map = {}
        progress = ProgressIndicator(f"Scanning {label}") if show_progress else None

        try:
            for file_info in walk_directory(path, exclude_patterns, progress):
                rel_path = os.path.relpath(file_info.path, path)
                file_info.hash = calculate_file_hash(file_info.path)
                file_map[rel_path] = file_info
        finally:
            if progress:
                progress.finish()

        return file_map

    files1 = build_file_map(path1, "path1")
    files2 = build_file_map(path2, "path2")

    keys1 = set(files1.keys())
    keys2 = set(files2.keys())

    # Files only in path1
    only_in_1 = keys1 - keys2
    result.only_in_path1 = sorted([
        {'path': k, 'size': files1[k].size, 'size_human': format_size(files1[k].size)}
        for k in only_in_1
    ], key=lambda x: x['path'])

    # Files only in path2
    only_in_2 = keys2 - keys1
    result.only_in_path2 = sorted([
        {'path': k, 'size': files2[k].size, 'size_human': format_size(files2[k].size)}
        for k in only_in_2
    ], key=lambda x: x['path'])

    # Common files - check for modifications
    common = keys1 & keys2
    for rel_path in common:
        f1 = files1[rel_path]
        f2 = files2[rel_path]

        if f1.hash != f2.hash:
            result.modified_files.append({
                'path': rel_path,
                'size_path1': f1.size,
                'size_path2': f2.size,
                'size_diff': f2.size - f1.size
            })
        else:
            result.identical_files.append(rel_path)

    result.modified_files.sort(key=lambda x: x['path'])

    # Summary
    result.summary = {
        'total_files_path1': len(files1),
        'total_files_path2': len(files2),
        'only_in_path1': len(result.only_in_path1),
        'only_in_path2': len(result.only_in_path2),
        'modified': len(result.modified_files),
        'identical': len(result.identical_files),
        'total_size_path1': sum(f.size for f in files1.values()),
        'total_size_path2': sum(f.size for f in files2.values())
    }

    return result


# ============================================================================
# Output Formatters
# ============================================================================

class OutputFormatter:
    """Base class for output formatters."""

    def format_analysis(self, result: AnalysisResult) -> str:
        raise NotImplementedError

    def format_compare(self, result: CompareResult) -> str:
        raise NotImplementedError


class TableFormatter(OutputFormatter):
    """Format output as human-readable tables."""

    def _make_table(self, headers: list, rows: list, title: str = "") -> str:
        """Create a simple ASCII table."""
        if not rows:
            return f"\n{title}\n  (no data)\n" if title else "  (no data)\n"

        # Calculate column widths
        widths = [len(h) for h in headers]
        for row in rows:
            for i, cell in enumerate(row):
                widths[i] = max(widths[i], len(str(cell)))

        # Build table
        lines = []
        if title:
            lines.append(f"\n{Colors.header(title)}")

        # Header
        header_line = " | ".join(
            Colors.bold(str(h).ljust(widths[i])) for i, h in enumerate(headers)
        )
        lines.append(header_line)
        lines.append("-+-".join("-" * w for w in widths))

        # Rows
        for row in rows:
            line = " | ".join(str(cell).ljust(widths[i]) for i, cell in enumerate(row))
            lines.append(line)

        return "\n".join(lines)

    def format_analysis(self, result: AnalysisResult) -> str:
        """Format analysis result as tables."""
        output = []

        # Header
        output.append(Colors.header(f"\n{'='*60}"))
        output.append(Colors.header(f"  FILE STATISTICS ANALYSIS"))
        output.append(Colors.header(f"{'='*60}"))
        output.append(f"\n{Colors.bold('Directory:')} {result.root_path}")
        output.append(f"{Colors.bold('Total Files:')} {Colors.info(str(result.total_files))}")
        output.append(f"{Colors.bold('Total Size:')} {Colors.info(format_size(result.total_size))}")
        output.append(f"{Colors.bold('Average File Age:')} {Colors.info(f'{result.average_age_days:.1f} days')}")

        if result.oldest_file:
            output.append(f"{Colors.bold('Oldest File:')} {result.oldest_file['path']}")
            output.append(f"              ({result.oldest_file['date']})")
        if result.newest_file:
            output.append(f"{Colors.bold('Newest File:')} {result.newest_file['path']}")
            output.append(f"              ({result.newest_file['date']})")

        # File count by extension
        rows = [(ext, count) for ext, count in list(result.count_by_extension.items())[:15]]
        output.append(self._make_table(
            ["Extension", "Count"],
            rows,
            "FILE COUNT BY EXTENSION (Top 15)"
        ))

        # Size by extension
        rows = [
            (ext, format_size(size), f"{size/result.total_size*100:.1f}%")
            for ext, size in list(result.size_by_extension.items())[:15]
        ]
        output.append(self._make_table(
            ["Extension", "Size", "Percentage"],
            rows,
            "SIZE BY EXTENSION (Top 15)"
        ))

        # Largest files
        rows = [
            (f['path'], f['size_human'])
            for f in result.largest_files
        ]
        output.append(self._make_table(
            ["File Path", "Size"],
            rows,
            "LARGEST FILES (Top 10)"
        ))

        # Duplicates
        dup_info = result.duplicates
        output.append(f"\n{Colors.header('DUPLICATE FILES')}")
        output.append(f"  {Colors.bold('Duplicate Groups:')} {dup_info['total_duplicate_groups']}")
        output.append(f"  {Colors.bold('Total Duplicate Files:')} {dup_info['total_duplicate_files']}")

        if dup_info['groups']:
            output.append(f"\n  {Colors.warning('Duplicate Groups (showing first 5):')}")
            for group in dup_info['groups'][:5]:
                output.append(f"\n  Hash: {group['hash'][:16]}... ({group['count']} files)")
                for f in group['files'][:3]:
                    output.append(f"    - {f}")
                if len(group['files']) > 3:
                    output.append(f"    ... and {len(group['files']) - 3} more")

        return "\n".join(output)

    def format_compare(self, result: CompareResult) -> str:
        """Format comparison result as tables."""
        output = []

        # Header
        output.append(Colors.header(f"\n{'='*60}"))
        output.append(Colors.header(f"  DIRECTORY COMPARISON"))
        output.append(Colors.header(f"{'='*60}"))
        output.append(f"\n{Colors.bold('Path 1:')} {result.path1}")
        output.append(f"{Colors.bold('Path 2:')} {result.path2}")

        # Summary
        s = result.summary
        output.append(f"\n{Colors.header('SUMMARY')}")
        output.append(f"  Files in Path 1: {s['total_files_path1']} ({format_size(s['total_size_path1'])})")
        output.append(f"  Files in Path 2: {s['total_files_path2']} ({format_size(s['total_size_path2'])})")
        output.append(f"  {Colors.warning(f'Only in Path 1: {s[\"only_in_path1\"]}')} files")
        output.append(f"  {Colors.warning(f'Only in Path 2: {s[\"only_in_path2\"]}')} files")
        output.append(f"  {Colors.error(f'Modified: {s[\"modified\"]}')} files")
        output.append(f"  {Colors.success(f'Identical: {s[\"identical\"]}')} files")

        # Only in path1
        if result.only_in_path1:
            rows = [(f['path'], f['size_human']) for f in result.only_in_path1[:20]]
            output.append(self._make_table(
                ["File", "Size"],
                rows,
                f"FILES ONLY IN PATH 1 (showing {min(20, len(result.only_in_path1))} of {len(result.only_in_path1)})"
            ))

        # Only in path2
        if result.only_in_path2:
            rows = [(f['path'], f['size_human']) for f in result.only_in_path2[:20]]
            output.append(self._make_table(
                ["File", "Size"],
                rows,
                f"FILES ONLY IN PATH 2 (showing {min(20, len(result.only_in_path2))} of {len(result.only_in_path2)})"
            ))

        # Modified files
        if result.modified_files:
            rows = [
                (f['path'], format_size(f['size_path1']), format_size(f['size_path2']),
