class JSONFormatter(OutputFormatter):
    """Format output as JSON."""

    def format_analysis(self, result: AnalysisResult) -> str:
        return json.dumps(result.to_dict(), indent=2)

    def format_compare(self, result: CompareResult) -> str:
        return json.dumps(result.to_dict(), indent=2)


class CSVFormatter(OutputFormatter):
    """Format output as CSV."""

    def format_analysis(self, result: AnalysisResult) -> str:
        output = io.StringIO()

        # Summary section
        output.write("# Summary\n")
        writer = csv.writer(output)
        writer.writerow(["Metric", "Value"])
        writer.writerow(["Root Path", result.root_path])
        writer.writerow(["Total Files", result.total_files])
        writer.writerow(["Total Size (bytes)", result.total_size])
        writer.writerow(["Total Size (human)", format_size(result.total_size)])
        writer.writerow(["Average Age (days)", f"{result.average_age_days:.2f}"])

        # Extension counts
        output.write("\n# File Count by Extension\n")
        writer.writerow(["Extension", "Count"])
        for ext, count in result.count_by_extension.items():
            writer.writerow([ext, count])

        # Extension sizes
        output.write("\n# Size by Extension\n")
        writer.writerow(["Extension", "Size (bytes)", "Size (human)"])
        for ext, size in result.size_by_extension.items():
            writer.writerow([ext, size, format_size(size)])

        # Largest files
        output.write("\n# Largest Files\n")
        writer.writerow(["Path", "Size (bytes)", "Size (human)"])
        for f in result.largest_files:
            writer.writerow([f['path'], f['size'], f['size_human']])

        # Duplicates
        output.write("\n# Duplicate Files\n")
        writer.writerow(["Hash", "File Path"])
        for group in result.duplicates.get('groups', []):
            for filepath in group['files']:
                writer.writerow([group['hash'], filepath])

        return output.getvalue()

    def format_compare(self, result: CompareResult) -> str:
        output = io.StringIO()
        writer = csv.writer(output)

        # Summary
        output.write("# Summary\n")
        writer.writerow(["Metric", "Value"])
        for key, value in result.summary.items():
            writer.writerow([key, value])

        # Only in path1
        output.write("\n# Only in Path 1\n")
        writer.writerow(["Path", "Size (bytes)"])
        for f in result.only_in_path1:
            writer.writerow([f['path'], f['size']])

        # Only in path2
        output.write("\n# Only in Path 2\n")
        writer.writerow(["Path", "Size (bytes)"])
        for f in result.only_in_path2:
            writer.writerow([f['path'], f['size']])

        # Modified
        output.write("\n# Modified Files\n")
        writer.writerow(["Path", "Size Path1", "Size Path2", "Size Diff"])
        for f in result.modified_files:
            writer.writerow([f['path'], f['size_path1'], f['size_path2'], f['size_diff']])

        return output.getvalue()


def get_formatter(format_type: str) -> OutputFormatter:
    """Get the appropriate formatter for the output type."""
    formatters = {
        'table': TableFormatter(),
        'json': JSONFormatter(),
        'csv': CSVFormatter()
    }
    return formatters.get(format_type, TableFormatter())


