```javascript
// Use the promise-based version of the 'fs' module
const fs = require('fs/promises');

/**
 * A helper function to fetch and parse JSON from a URL.
 * It uses the native fetch API and throws an error for non-ok responses.
 * @param {string} url The URL to fetch.
 * @returns {Promise<any>} A promise that resolves to the parsed JSON data.
 */
async function fetchJSON(url) {
    const response = await fetch(url);
    if (!response.ok) {
        throw new Error(`Request failed with status ${response.status}: ${response.statusText}`);
    }
    // .json() reads the stream to completion and parses the body text as JSON
    return response.json();
}

/**
 * Fetches user data for a given userId.
 * @param {number} userId The ID of the user.
 * @returns {Promise<object>} A promise that resolves to the user data.
 */
function fetchUserData(userId) {
    return fetchJSON(`https://jsonplaceholder.typicode.com/users/${userId}`);
}

/**
 * Fetches all posts for a given userId.
 * @param {number} userId The ID of the user.
 * @returns {Promise<Array<object>>} A promise that resolves to an array of posts.
 */
function fetchUserPosts(userId) {
    return fetchJSON(`https://jsonplaceholder.typicode.com/users/${userId}/posts`);
}

/**
 * Processes an array of user IDs in parallel.
 * For each user, it fetches their data and posts sequentially.
 * @param {Array<number>} userIds An array of user IDs.
 * @returns {Promise<Array<object>>} A promise that resolves to an array of processed user objects.
 */
async function processUsers(userIds) {
    // Create an array of promises. Each promise represents the full processing for one user.
    const userProcessingPromises = userIds.map(async (id) => {
        // For each user, we first get their data, then their posts.
        // This maintains the sequential logic per-user from the original code.
        const user = await fetchUserData(id);
        const posts = await fetchUserPosts(id);

        // Combine the results into a single object
        return {
            ...user,
            posts: posts,
            postCount: posts.length
        };
    });

    // Promise.all runs all the user-processing promises in parallel.
    // It will wait for all of them to resolve, or reject as soon as one of them fails.
    // This perfectly replaces the manual counter and error flag logic.
    return Promise.all(userProcessingPromises);
}

/**
 * Saves the processed results to a JSON file and returns info about the file.
 * @param {Array<object>} results The data to save.
 * @param {string} filename The name of the file to save to.
 * @returns {Promise<object>} A promise that resolves to an info object.
 */
async function saveResults(results, filename) {
    const json = JSON.stringify(results, null, 2);

    // Write the file, then get its stats.
    await fs.writeFile(filename, json, 'utf8');
    const stats = await fs.stat(filename);

    return { filename, size: stats.size, count: results.length };
}

// Main execution wrapped in an async IIFE (Immediately Invoked Function Expression)
// This allows us to use `await` at the top level of the script.
(async () => {
    try {
        const userIds = [1, 2, 3, 4, 5];

        const results = await processUsers(userIds);
        console.log(`Processed ${results.length} users`);

        const info = await saveResults(results, 'users.json');
        console.log(`Saved ${info.count} users to ${info.filename} (${info.size} bytes)`);

    } catch (err) {
        // A single catch block handles errors from any of the awaited promises.
        console.error('An error occurred during execution:', err.message);
        process.exit(1);
    }
})();
