    disabled={disabled}
    className={[
      'min-w-[2rem] h-8 px-2 text-sm font-medium rounded-md transition-all duration-150',
      'focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:ring-offset-1',
      active
        ? 'bg-indigo-600 text-white shadow-sm'
        : disabled
        ? 'text-slate-300 cursor-not-allowed'
        : 'text-slate-600 hover:bg-slate-100 hover:text-slate-900',
    ].join(' ')}
  >
    {children}
  </button>
);

// ─── Utility: get nested value as string ──────────────────────────────────────

function getValueAsString<T>(row: T, key: keyof T): string {
  const val = row[key];
  if (val === null || val === undefined) return '';
  return String(val).toLowerCase();
}

// ─── Main DataTable Component ─────────────────────────────────────────────────

export function DataTable<T extends { id: string | number }>({
  data,
  columns,
  pageSizeOptions = [10, 25, 50],
  defaultPageSize = 10,
  className = '',
  emptyMessage = 'No records found.',
}: DataTableProps<T>) {
  const tableId = useId();

  // ── State ──────────────────────────────────────────────────────────────────
  const [search, setSearch] = useState('');
  const [sort, setSort] = useState<SortState>({ key: null, direction: null });
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState(defaultPageSize);
  const [selectedIds, setSelectedIds] = useState<Set<string | number>>(new Set());

  // ── Filtering ──────────────────────────────────────────────────────────────
  const filtered = useMemo(() => {
    if (!search.trim()) return data;
    const term = search.toLowerCase().trim();
    return data.filter((row) =>
      columns.some((col) => getValueAsString(row, col.key).includes(term))
    );
  }, [data, search, columns]);

  // ── Sorting ────────────────────────────────────────────────────────────────
  const sorted = useMemo(() => {
    if (!sort.key || !sort.direction) return filtered;
    return [...filtered].sort((a, b) => {
      const aVal = getValueAsString(a, sort.key as keyof T);
      const bVal = getValueAsString(b, sort.key as keyof T);
      const cmp = aVal.localeCompare(bVal, undefined, { numeric: true, sensitivity: 'base' });
      return sort.direction === 'asc' ? cmp : -cmp;
    });
  }, [filtered, sort]);

  // ── Pagination ─────────────────────────────────────────────────────────────
  const totalPages = Math.max(1, Math.ceil(sorted.length / pageSize));
  const safePage = Math.min(page, totalPages);

  const paginated = useMemo(() => {
    const start = (safePage - 1) * pageSize;
    return sorted.slice(start, start + pageSize);
  }, [sorted, safePage, pageSize]);

  // Reset to page 1 when search/sort/pageSize changes
  const handleSearch = useCallback((value: string) => {
    setSearch(value);
    setPage(1);
  }, []);

  const handlePageSize = useCallback((size: number) => {
    setPageSize(size);
    setPage(1);
  }, []);

  // ── Sorting handler ────────────────────────────────────────────────────────
  const handleSort = useCallback((key: string) => {
    setSort((prev) => {
      if (prev.key !== key) return { key, direction: 'asc' };
      if (prev.direction === 'asc') return { key, direction: 'desc' };
      return { key: null, direction: null };
    });
    setPage(1);
  }, []);

  // ── Selection ──────────────────────────────────────────────────────────────
  const pageIds = useMemo(() => paginated.map((r) => r.id), [paginated]);
  const allPageSelected = pageIds.length > 0 && pageIds.every((id) => selectedIds.has(id));
  const somePageSelected = pageIds.some((id) => selectedIds.has(id)) && !allPageSelected;

  const handleSelectAll = useCallback(
    (checked: boolean) => {
      setSelectedIds((prev) => {
        const next = new Set(prev);
        pageIds.forEach((id) => (checked ? next.add(id) : next.delete(id)));
        return next;
      });
    },
    [pageIds]
  );

  const handleSelectRow = useCallback((id: string | number, checked: boolean) => {
    setSelectedIds((prev) => {
      const next = new Set(prev);
      checked ? next.add(id) : next.delete(id);
      return next;
    });
  }, []);

  const clearSelection = useCallback(() => setSelectedIds(new Set()), []);

  // ── Pagination page numbers ────────────────────────────────────────────────
  const pageNumbers = useMemo(() => {
    const delta = 1;
    const range: (number | '...')[] = [];
    const left = Math.max(2, safePage - delta);
    const right = Math.min(totalPages - 1, safePage + delta);

    range.push(1);
    if (left > 2) range.push('...');
    for (let i = left; i <= right; i++) range.push(i);
    if (right < totalPages - 1) range.push('...');
    if (totalPages > 1) range.push(totalPages);

    return range;
  }, [safePage, totalPages]);

  // ── Render ─────────────────────────────────────────────────────────────────
  return (
    <div className={`flex flex-col gap-4 ${className}`}>

      {/* ── Toolbar ── */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3">

        {/* Search */}
        <div className="relative flex-1 max-w-sm">
          <div className="absolute inset-y-0 left-3 flex items-center pointer-events-none">
            <SearchIcon />
          </div>
          <input
            id={`${tableId}-search`}
            type="text"
            value={search}
            onChange={(e) => handleSearch(e.target.value)}
            placeholder="Search all columns…"
            className={[
              'w-full pl-9 pr-9 py-2 text-sm rounded-lg border border-slate-200',
              'bg-white text-slate-900 placeholder-slate-400',
              'focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:border-transparent',
              'transition-shadow duration-150',
            ].join(' ')}
          />
          {search && (
            <button
              onClick={() => handleSearch('')}
              className="absolute inset-y-0 right-3 flex items-center text-slate-400 hover:text-slate-600 transition-colors"
              aria-label="Clear search"
            >
              <XIcon />
            </button>
          )}
        </div>

        {/* Right controls */}
        <div className="flex items-center gap-3">
          {/* Selected count badge */}
          {selectedIds.size > 0 && (
            <div className="flex items-center gap-2 px-3 py-1.5 bg-indigo-50 border border-indigo-200 rounded-lg">
              <span className="text-sm font-medium text-indigo-700">
                {selectedIds.size} selected
              </span>
              <button
                onClick={clearSelection}
                className="text-indigo-400 hover:text-indigo-600 transition-colors"
                aria-label="Clear selection"
              >
                <XIcon />
              </button>
            </div>
          )}

          {/* Page size selector */}
          <div className="flex items-center gap-2">
            <label htmlFor={`${tableId}-pagesize`} className="text-sm text-slate-500 whitespace-nowrap">
              Rows per page
            </label>
            <select
              id={`${tableId}-pagesize`}
              value={pageSize}
              onChange={(e) => handlePageSize(Number(e.target.value))}
              className={[
                'text-sm border border-slate-200 rounded-lg px-2 py-1.5 bg-white',
                'text-slate-700 focus:outline-none focus:ring-2 focus:ring-indigo-500',
                'cursor-pointer transition-shadow duration-150',
              ].join(' ')}
            >
              {pageSizeOptions.map((s) => (
                <option key={s} value={s}>{s}</option>
              ))}
            </select>
          </div>
        </div>
      </div>

      {/* ── Table ── */}
      <div className="overflow-x-auto rounded-xl border border-slate-200 shadow-sm">
        <table className="w-full text-sm text-left border-collapse">
          <thead>
            <tr className="bg-slate-50 border-b border-slate-200">
              {/* Select-all checkbox */}
              <th className="w-10 px-4 py-3">
                <Checkbox
                  checked={allPageSelected}
                  indeterminate={somePageSelected}
                  onChange={handleSelectAll}
                  label="Select all on page"
                />
              </th>

              {columns.map((col) => (
                <th
                  key={String(col.key)}
                  className={[
                    'px-4 py-3 font-semibold text-slate-600 whitespace-nowrap',
                    col.sortable !== false
                      ? 'cursor-pointer select-none hover:bg-slate-100 transition-colors duration-150'
                      : '',
                    col.className ?? '',
                  ].join(' ')}
                  onClick={() => col.sortable !== false && handleSort(String(col.key))}
                  aria-sort={
                    sort.key === String(col.key)
                      ? sort.direction === 'asc' ? 'ascending' : 'descending'
                      : 'none'
                  }
                >
                  <div className="flex items-center gap-1.5">
                    <span>{col.header}</span>
                    {col.sortable !== false && (
                      <span className={sort.key === String(col.key) ? 'text-indigo-600' : 'text-slate-400'}>
                        <SortIcon direction={sort.key === String(col.key) ? sort.direction : null} />
                      </span>
                    )}
                  </div>
                </th>
              ))}
            </tr>
          </thead>

          <tbody className="divide-y divide-slate-100">
            {paginated.length === 0 ? (
              <tr>
                <td
                  colSpan={columns.length + 1}
                  className="px-4 py-16 text-center text-slate-400 text-sm"
                >
                  <div className="flex flex-col items-center gap-2">
                    <svg className="w-10 h-10 text-slate-200" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5}
                        d="M20 13V6a2 2 0 00-2-2H6a2 2 0 00-2 2v7m16 0v5a2 2 0 01-2 2H6a2 2 0 01-2-2v-5m16 0h-2.586a1 1 0 00-.707.293l-2.414 2.414a1 1 0 01-.707.293h-3.172a1 1 0 01-.707-.293l-2.414-2.414A1 1 0 006.586 13H4" />
                    </svg>
                    <span>{emptyMessage}</span>
                  </div>
                </td>
              </tr>
            ) : (
              paginated.map((row, rowIdx) => {
                const isSelected = selectedIds.has(row.id);
                return (
                  <tr
                    key={row.id}
                    className={[
                      'group transition-colors duration-100',
                      isSelected
                        ? 'bg-indigo-50/70'
                        : rowIdx % 2 === 0
                        ? 'bg-white hover:bg-slate-50'
                        : 'bg-slate-50/40 hover:bg-slate-50',
                    ].join(' ')}
                  >
                    {/* Row checkbox */}
                    <td className="w-10 px-4 py-3">
                      <Checkbox
                        checked={isSelected}
                        onChange={(checked) => handleSelectRow(row.id, checked)}
                        label={`Select row ${row.id}`}
                      />
                    </td>

                    {columns.map((col) => (
                      <td
                        key={String(col.key)}
                        className={`px-4 py-3 text-slate-700 ${col.className ?? ''}`}
                      >
                        {col.render
                          ? col.render(row[col.key], row)
                          : String(row[col.key] ?? '')}
                      </td>
                    ))}
                  </tr>
                );
              })
            )}
          </tbody>
        </table>
      </div>

      {/* ── Footer / Pagination ── */}
      <div className="flex flex-col sm:flex-row items-center justify-between gap-3 text-sm text-slate-500">
        {/* Record count */}
        <span>
          {sorted.length === 0
            ? 'No records'
            : `Showing ${(safePage - 1) * pageSize + 1}–${Math.min(safePage * pageSize, sorted.length)} of ${sorted.length} record${sorted.length !== 1 ? 's' : ''}${
                search ? ` (filtered from ${data.length})` : ''
              }`}
        </span>

        {/* Page controls */}
        <div className="flex items-center gap-1">
          {/* First */}
          <PaginationButton onClick={() => setPage(1)} disabled={safePage === 1}>
            «
          </PaginationButton>
          {/* Prev */}
          <PaginationButton onClick={() => setPage((p) => Math.max(1, p - 1))} disabled={safePage === 1}>
            ‹
          </PaginationButton>

          {pageNumbers.map((num, i) =>
            num === '...' ? (
              <span key={`ellipsis-${i}`} className="px-1 text-slate-400 select-none">
                …
              </span>
            ) : (
              <PaginationButton
                key={num}
                onClick={() => setPage(num as number)}
                disabled={false}
                active={safePage === num}
              >
                {num}
              </PaginationButton>
            )
          )}

          {/* Next */}
          <PaginationButton onClick={() => setPage((p) => Math.min(totalPages, p + 1))} disabled={safePage === totalPages}>
            ›
          </PaginationButton>
          {/* Last */}
          <PaginationButton onClick={() => setPage(totalPages)} disabled={safePage === totalPages}>
            »
          </PaginationButton>
        </div>
      </div>
    </div>
  );
}
