```javascript
const WebSocket = require('ws');
const http = require('http');
const fs = require('fs');
const path = require('path');

// ─── Constants ────────────────────────────────────────────────────────────────
const PORT = process.env.PORT || 3000;
const MAX_HISTORY = 50;
const HEARTBEAT_INTERVAL = 30_000; // 30 s
const NICKNAME_MAX_LEN = 24;
const MESSAGE_MAX_LEN = 1000;
const ROOM_NAME_MAX_LEN = 32;
const ROOM_NAME_RE = /^[a-zA-Z0-9_-]+$/;

// ─── In-memory state ──────────────────────────────────────────────────────────
/**
 * rooms: Map<roomName, { clients: Set<WebSocket>, history: Message[] }>
 * Each WebSocket client carries extra properties:
 *   client.nickname  – string
 *   client.rooms     – Set<string>
 *   client.isAlive   – boolean (heartbeat)
 *   client.id        – unique numeric id (for logging)
 */
const rooms = new Map();
let clientIdCounter = 0;

// ─── Helpers ──────────────────────────────────────────────────────────────────

/** Ensure a room exists and return it. */
function getOrCreateRoom(name) {
  if (!rooms.has(name)) {
    rooms.set(name, { clients: new Set(), history: [] });
    console.log(`[room] created: #${name}`);
  }
  return rooms.get(name);
}

/** Remove a room if it has no clients. */
function pruneRoom(name) {
  const room = rooms.get(name);
  if (room && room.clients.size === 0) {
    rooms.delete(name);
    console.log(`[room] pruned: #${name}`);
  }
}

/** Build a typed message object. */
function buildMessage(type, room, user, content, extra = {}) {
  return {
    type,       // 'message' | 'system' | 'typing' | 'history' | 'error'
                // | 'joined' | 'left' | 'rooms' | 'members'
    room,
    user,
    content,
    timestamp: new Date().toISOString(),
    ...extra,
  };
}

/** Safely serialise and send to a single client. */
function send(client, payload) {
  if (client.readyState === WebSocket.OPEN) {
    client.send(JSON.stringify(payload));
  }
}

/** Broadcast to every client in a room, optionally excluding one. */
function broadcast(roomName, payload, exclude = null) {
  const room = rooms.get(roomName);
  if (!room) return;
  const data = JSON.stringify(payload);
  for (const client of room.clients) {
    if (client !== exclude && client.readyState === WebSocket.OPEN) {
      client.send(data);
    }
  }
}

/** Append a message to room history, capping at MAX_HISTORY. */
function addToHistory(roomName, message) {
  const room = rooms.get(roomName);
  if (!room) return;
  room.history.push(message);
  if (room.history.length > MAX_HISTORY) {
    room.history.shift();
  }
}

/** Return a sorted list of all room names. */
function listRooms() {
  return [...rooms.keys()].sort();
}

/** Return nicknames of all clients in a room. */
function listMembers(roomName) {
  const room = rooms.get(roomName);
  if (!room) return [];
  return [...room.clients].map((c) => c.nickname).sort();
}

/** Validate and sanitise a nickname. Returns null if invalid. */
function sanitiseNickname(raw) {
  if (typeof raw !== 'string') return null;
  const trimmed = raw.trim().slice(0, NICKNAME_MAX_LEN);
  if (trimmed.length < 1) return null;
  return trimmed;
}

/** Validate a room name. Returns null if invalid. */
function sanitiseRoomName(raw) {
  if (typeof raw !== 'string') return null;
  const trimmed = raw.trim().slice(0, ROOM_NAME_MAX_LEN);
  if (!ROOM_NAME_RE.test(trimmed)) return null;
  return trimmed;
}

// ─── HTTP server (serves the static client) ───────────────────────────────────
const httpServer = http.createServer((req, res) => {
  if (req.method !== 'GET') {
    res.writeHead(405);
    return res.end('Method Not Allowed');
  }

  const safePath = req.url === '/' ? '/index.html' : req.url;
  const filePath = path.join(__dirname, 'public', path.normalize(safePath));

  // Prevent directory traversal
  if (!filePath.startsWith(path.join(__dirname, 'public'))) {
    res.writeHead(403);
    return res.end('Forbidden');
  }

  fs.readFile(filePath, (err, data) => {
    if (err) {
      res.writeHead(404);
      return res.end('Not Found');
    }
    const ext = path.extname(filePath);
    const mime = { '.html': 'text/html', '.js': 'text/javascript', '.css': 'text/css' };
    res.writeHead(200, { 'Content-Type': mime[ext] || 'text/plain' });
    res.end(data);
  });
});

// ─── WebSocket server ─────────────────────────────────────────────────────────
const wss = new WebSocket.Server({ server: httpServer });

// ── Heartbeat: detect dead connections ────────────────────────────────────────
const heartbeatTimer = setInterval(() => {
  wss.clients.forEach((client) => {
    if (!client.isAlive) {
      console.log(`[heartbeat] terminating dead client #${client.id}`);
      return client.terminate();
    }
    client.isAlive = false;
    client.ping();
  });
}, HEARTBEAT_INTERVAL);

wss.on('close', () => clearInterval(heartbeatTimer));

// ── Connection handler ────────────────────────────────────────────────────────
wss.on('connection', (client, req) => {
  // Initialise client metadata
  client.id = ++clientIdCounter;
  client.nickname = `Guest${client.id}`;
  client.rooms = new Set();
  client.isAlive = true;

  const ip = req.socket.remoteAddress;
  console.log(`[connect] client #${client.id} (${ip}) as "${client.nickname}"`);

  // Send a welcome message with the available rooms
  send(client, buildMessage('system', null, 'Server',
    `Welcome, ${client.nickname}! Use /nick <name> to set your nickname.`,
    { rooms: listRooms() }
  ));

  // ── Heartbeat pong ──────────────────────────────────────────────────────────
  client.on('pong', () => { client.isAlive = true; });

  // ── Message handler ─────────────────────────────────────────────────────────
  client.on('message', (raw) => {
    let data;
    try {
      data = JSON.parse(raw);
    } catch {
      return send(client, buildMessage('error', null, 'Server', 'Invalid JSON.'));
    }

    const { type } = data;

    switch (type) {

      // ── Set nickname ──────────────────────────────────────────────────────
      case 'nick': {
        const nick = sanitiseNickname(data.nickname);
        if (!nick) {
          return send(client, buildMessage('error', null, 'Server',
            'Invalid nickname. Must be 1–24 non-empty characters.'));
        }

        // Check for duplicates across all connected clients
        const taken = [...wss.clients].some(
          (c) => c !== client && c.nickname === nick
        );
        if (taken) {
          return send(client, buildMessage('error', null, 'Server',
            `Nickname "${nick}" is already taken.`));
        }

        const oldNick = client.nickname;
        client.nickname = nick;
        console.log(`[nick] #${client.id}: "${oldNick}" → "${nick}"`);

        // Confirm to the client
        send(client, buildMessage('system', null, 'Server',
          `Nickname changed to "${nick}".`, { nickname: nick }));

        // Notify all rooms this client is in
        for (const roomName of client.rooms) {
          const msg = buildMessage('system', roomName, 'Server',
            `${oldNick} is now known as ${nick}.`);
          addToHistory(roomName, msg);
          broadcast(roomName, msg, client);
        }
        break;
      }

      // ── Join room ─────────────────────────────────────────────────────────
      case 'join': {
        const roomName = sanitiseRoomName(data.room);
        if (!roomName) {
          return send(client, buildMessage('error', null, 'Server',
            'Invalid room name. Use letters, numbers, hyphens, underscores only.'));
        }

        if (client.rooms.has(roomName)) {
          return send(client, buildMessage('error', roomName, 'Server',
            `You are already in #${roomName}.`));
        }

        const room = getOrCreateRoom(roomName);
        room.clients.add(client);
        client.rooms.add(roomName);

        console.log(`[join] #${client.id} "${client.nickname}" → #${roomName}`);

        // Send history to the joining client
        send(client, buildMessage('history', roomName, 'Server', null, {
          messages: room.history,
          members: listMembers(roomName),
        }));

        // Broadcast join notification to the room
        const joinMsg = buildMessage('system', roomName, 'Server',
          `${client.nickname} joined #${roomName}.`,
          { event: 'joined', who: client.nickname });
        addToHistory(roomName, joinMsg);
        broadcast(roomName, joinMsg, client);

        // Confirm to the joining client
        send(client, buildMessage('joined', roomName, 'Server',
          `You joined #${roomName}.`,
          { members: listMembers(roomName) }));
        break;
      }

      // ── Leave room ────────────────────────────────────────────────────────
      case 'leave': {
        const roomName = sanitiseRoomName(data.room);
        if (!roomName || !client.rooms.has(roomName)) {
          return send(client, buildMessage('error', null, 'Server',
            `You are not in #${roomName || '?'}.`));
        }

        leaveRoom(client, roomName);
        send(client, buildMessage('left', roomName, 'Server',
          `You left #${roomName}.`));
        break;
      }

      // ── Chat message ──────────────────────────────────────────────────────
      case 'message': {
        const roomName = sanitiseRoomName(data.room);
        if (!roomName) {
          return send(client, buildMessage('error', null, 'Server', 'Invalid room.'));
        }
        if (!client.rooms.has(roomName)) {
          return send(client, buildMessage('error', roomName, 'Server',
            `Join #${roomName} first.`));
        }

        const content = typeof data.content === 'string'
          ? data.content.trim().slice(0, MESSAGE_MAX_LEN)
          : '';
        if (!content) {
          return send(client, buildMessage('error', roomName, 'Server',
            'Empty message.'));
        }

        const msg = buildMessage('message', roomName, client.nickname, content);
        addToHistory(roomName, msg);
        broadcast(roomName, msg); // include sender so they see their own message
        console.log(`[msg] #${roomName} <${client.nickname}>: ${content.slice(0, 60)}`);
        break;
      }

      // ── Typing indicator ──────────────────────────────────────────────────
      case 'typing': {
        const roomName = sanitiseRoomName(data.room);
        if (!roomName || !client.rooms.has(roomName)) return;

        const isTyping = Boolean(data.isTyping);
        broadcast(roomName,
          buildMessage('typing', roomName, client.nickname, null, { isTyping }),
          client // don't echo back to sender
        );
        break;
      }

      // ── List rooms ────────────────────────────────────────────────────────
      case 'rooms': {
        send(client, buildMessage('rooms', null, 'Server', null,
          { rooms: listRooms() }));
        break;
      }

      // ── List members ──────────────────────────────────────────────────────
      case 'members': {
        const roomName = sanitiseRoomName(data.room);
        if (!roomName || !client.rooms.has(roomName)) {
          return send(client, buildMessage('error', null, 'Server',
            `You are not in #${roomName || '?'}.`));
        }
        send(client, buildMessage('members', roomName, 'Server', null,
          { members: listMembers(roomName) }));
        break;
      }

      default:
        send(client, buildMessage('error', null, 'Server',
          `Unknown message type: "${type}".`));
    }
  });

  // ── Disconnect handler ──────────────────────────────────────────────────────
  client.on('close', (code, reason) => {
    console.log(`[disconnect] #${client.id} "${client.nickname}" (${code})`);
    // Leave all rooms cleanly
    for (const roomName of [...client.rooms]) {
      leaveRoom(client, roomName);
    }
  });

  client.on('error', (err) => {
    console.error(`[error] client #${client.id}:`, err.message);
  });
});

// ── Shared leave-room logic ───────────────────────────────────────────────────
function leaveRoom(client, roomName) {
  const room = rooms.get(roomName);
  if (!room) return;

  room.clients.delete(client);
  client.rooms.delete(roomName);

  console.log(`[leave] #${client.id} "${client.nickname}" ← #${roomName}`);

  const leaveMsg = buildMessage('system', roomName, 'Server',
    `${client.nickname} left #${roomName}.`,
    { event: 'left', who: client.nickname });
  addToHistory(roomName, leaveMsg);
  broadcast(roomName, leaveMsg);

  pruneRoom(roomName);
}

// ─── Start ────────────────────────────────────────────────────────────────────
httpServer.listen(PORT, () => {
  console.log(`Chat server running → http://localhost:${PORT}`);
  console.log('WebSocket endpoint  → ws://localhost:' + PORT);
});
