def cmd_analyze(args: argparse.Namespace) -> int:
    root = Path(args.path).expanduser().resolve()
    if not root.is_dir():
        print(Color.error(f"Error: '{root}' is not a directory."), file=sys.stderr)
        return 1

    excludes: List[str] = args.exclude or []
    scanner = Scanner(exclude_patterns=excludes)
    analyzer = Analyzer()
    formatter = Formatter(args.format)

    progress = Progress("Scanning")
    files, errors = scanner.scan(root, progress=progress)
    progress.done()

    result = analyzer.analyze(root, files, errors)
    print(formatter.format_analysis(result))
    return 0


def cmd_compare(args: argparse.Namespace) -> int:
    path1 = Path(args.path1).expanduser().resolve()
    path2 = Path(args.path2).expanduser().resolve()

    for p in (path1, path2):
        if not p.is_dir():
            print(Color.error(f"Error: '{p}' is not a directory."), file=sys.stderr)
            return 1

    excludes: List[str] = args.exclude or []
    scanner = Scanner(exclude_patterns=excludes)
    comparator = Comparator()
    formatter = Formatter(args.format)

    progress1 = Progress(f"Scanning {path1.name}")
    files1, errors1 = scanner.scan(path1, progress=progress1)
    progress1.done()

    progress2 = Progress(f"Scanning {path2.name}")
    files2, errors2 = scanner.scan(path2, progress=progress2)
    progress2.done()

    result = comparator.compare(path1, path2, files1, files2, errors1 + errors2)
    print(formatter.format_compare(result))
    return 0


